    # ========================================================
    # MANE
    #
    # One coherent ribbon hanging mostly to the left.
    #
    # The root follows the crest.
    # The lower edge is intentionally irregular.
    # ========================================================

    def build_mane():

        stations = [
            # y, root z, tip x, tip z, bone
            (
                -1.060,
                2.050,
                -0.060,
                1.905,
                "head"
            ),

            (
                -1.000,
                2.055,
                -0.080,
                1.875,
                "head"
            ),

            (
                -0.935,
                2.060,
                -0.115,
                1.835,
                "neck"
            ),

            (
                -0.870,
                2.045,
                -0.145,
                1.785,
                "neck"
            ),

            (
                -0.805,
                2.020,
                -0.165,
                1.730,
                "neck"
            ),

            (
                -0.740,
                1.985,
                -0.180,
                1.675,
                "neck"
            ),

            (
                -0.680,
                1.945,
                -0.180,
                1.625,
                "neck"
            ),

            (
                -0.625,
                1.895,
                -0.165,
                1.585,
                "neck"
            ),

            (
                -0.580,
                1.850,
                -0.145,
                1.560,
                "neck"
            ),
        ]

        thickness = 0.018

        verts = []
        faces = []

        for station in stations:

            (
                y,
                root_z,
                tip_x,
                tip_z,
                bone
            ) = station

            verts.extend(
                [
                    (
                        -thickness,
                        y,
                        root_z
                    ),

                    (
                        thickness,
                        y,
                        root_z
                    ),

                    (
                        tip_x - thickness,
                        y + 0.020,
                        tip_z
                    ),

                    (
                        tip_x + thickness,
                        y + 0.020,
                        tip_z
                    ),
                ]
            )

        for index in range(
            len(stations) - 1
        ):

            a = (
                index * 4
            )

            b = (
                index + 1
            ) * 4

            faces.extend(
                [
                    (
                        a,
                        b,
                        b + 2,
                        a + 2
                    ),

                    (
                        a + 1,
                        a + 3,
                        b + 3,
                        b + 1
                    ),

                    (
                        a,
                        a + 1,
                        b + 1,
                        b
                    ),

                    (
                        a + 2,
                        b + 2,
                        b + 3,
                        a + 3
                    ),
                ]
            )

        faces.append(
            (
                0,
                2,
                3,
                1
            )
        )

        last = (
            len(stations) - 1
        ) * 4

        faces.append(
            (
                last,
                last + 1,
                last + 3,
                last + 2
            )
        )

        mesh = bpy.data.meshes.new(
            "RiverwatchV11ManeMesh"
        )

        mesh.from_pydata(
            verts,
            [],
            faces
        )

        mesh.update()

        obj = bpy.data.objects.new(
            "RiverwatchV11Mane",
            mesh
        )

        bpy.context.collection.objects.link(
            obj
        )

        obj.data.materials.append(
            mane_mat
        )

        neck_group = obj.vertex_groups.new(
            name="neck"
        )

        head_group = obj.vertex_groups.new(
            name="head"
        )

        for vertex in obj.data.vertices:

            if vertex.co.y <= -0.975:

                head_group.add(
                    [vertex.index],
                    1.0,
                    "REPLACE"
                )

            else:

                neck_group.add(
                    [vertex.index],
                    1.0,
                    "REPLACE"
                )

        apply_subdivision(
            obj,
            1
        )

        smooth(
            obj
        )

        bind_armature(
            obj
        )

        return obj

    build_mane()

    # Simple forelock.
