    # ========================================================
    # TAIL CONTROL CAGE
    #
    # Broad at the upper-middle.
    # Narrow root.
    # Natural tapered end.
    # ========================================================

    def build_tail():

        sections = [
            (
                0.000,
                1.040,
                1.495,
                0.055,
                0.048
            ),

            (
                0.000,
                1.100,
                1.445,
                0.070,
                0.058
            ),

            (
                -0.005,
                1.175,
                1.370,
                0.090,
                0.068
            ),

            (
                -0.010,
                1.265,
                1.270,
                0.115,
                0.078
            ),

            (
                0.000,
                1.360,
                1.145,
                0.135,
                0.086
            ),

            (
                0.010,
                1.455,
                1.000,
                0.145,
                0.090
            ),

            (
                0.010,
                1.545,
                0.850,
                0.142,
                0.087
            ),

            (
                0.000,
                1.625,
                0.705,
                0.125,
                0.080
            ),

            (
                -0.010,
                1.690,
                0.575,
                0.100,
                0.070
            ),

            (
                -0.015,
                1.735,
                0.465,
                0.070,
                0.055
            ),

            (
                -0.018,
                1.765,
                0.385,
                0.035,
                0.034
            ),
        ]

        weights = [
            {
                "tail.1": 1.0
            },

            {
                "tail.1": 1.0
            },

            {
                "tail.1": 1.0
            },

            {
                "tail.1": 0.75,
                "tail.2": 0.25
            },

            {
                "tail.1": 0.45,
                "tail.2": 0.55
            },

            {
                "tail.1": 0.20,
                "tail.2": 0.80
            },

            {
                "tail.2": 1.0
            },

            {
                "tail.2": 1.0
            },

            {
                "tail.2": 1.0
            },

            {
                "tail.2": 1.0
            },

            {
                "tail.2": 1.0
            },
        ]

        centers = [
            Vector(
                (
                    section[0],
                    section[1],
                    section[2]
                )
            )
            for section in sections
        ]

        rings = 8

        verts = []
        faces = []

        for section_index, section in enumerate(
            sections
        ):

            center = centers[
                section_index
            ]

            lateral, depth = limb_frame(
                centers,
                section_index
            )

            rx = section[3]
            rd = section[4]

            for ring_index in range(
                rings
            ):

                angle = (
                    math.tau
                    * float(ring_index)
                    / float(rings)
                )

                point = (
                    center
                    + lateral
                    * (
                        math.cos(angle)
                        * rx
                    )
                    + depth
                    * (
                        math.sin(angle)
                        * rd
                    )
                )

                verts.append(
                    tuple(point)
                )

        for section_index in range(
            len(sections) - 1
        ):

            first = (
                section_index * rings
            )

            second = (
                section_index + 1
            ) * rings

            for ring_index in range(
                rings
            ):

                next_ring = (
                    ring_index + 1
                ) % rings

                faces.append(
                    (
                        first + ring_index,
                        second + ring_index,
                        second + next_ring,
                        first + next_ring
                    )
                )

        mesh = bpy.data.meshes.new(
            "RiverwatchV11TailMesh"
        )

        mesh.from_pydata(
            verts,
            [],
            faces
        )

        mesh.update()

        obj = bpy.data.objects.new(
            "RiverwatchV11Tail",
            mesh
        )

        bpy.context.collection.objects.link(
            obj
        )

        obj.data.materials.append(
            mane_mat
        )

        tail1 = obj.vertex_groups.new(
            name="tail.1"
        )

        tail2 = obj.vertex_groups.new(
            name="tail.2"
        )

        for section_index, weight_map in enumerate(
            weights
        ):

            section_vertices = list(
                range(
                    section_index * rings,
                    section_index * rings + rings
                )
            )

            for group_name, weight in weight_map.items():

                if group_name == "tail.1":

                    tail1.add(
                        section_vertices,
                        weight,
                        "REPLACE"
                    )

                else:

                    tail2.add(
                        section_vertices,
                        weight,
                        "REPLACE"
                    )

        apply_subdivision(
            obj,
            1
        )

        smooth(
            obj
        )

        bind_armature(
            obj
        )

        return obj

    build_tail()

    # ========================================================
