    # ========================================================
    # LEG LOFT HELPER
    #
    # Stations:
    #
    # y
    # z
    # lateral radius
    # depth radius
    #
    # Every station follows explicit anatomical landmarks.
    # ========================================================

    def build_leg(
        name,
        center_x,
        sections,
        group_name
    ):

        centers = [
            Vector(
                (
                    center_x,
                    section[0],
                    section[1]
                )
            )
            for section in sections
        ]

        ring_count = 10

        verts = []
        faces = []

        def frame_at(
            index
        ):

            if index == 0:

                tangent = (
                    centers[1]
                    - centers[0]
                )

            elif index == len(
                centers
            ) - 1:

                tangent = (
                    centers[-1]
                    - centers[-2]
                )

            else:

                tangent = (
                    centers[
                        index + 1
                    ]
                    - centers[
                        index - 1
                    ]
                )

            if tangent.length < 0.00001:

                tangent = Vector(
                    (
                        0.0,
                        0.0,
                        -1.0
                    )
                )

            tangent.normalize()

            lateral = Vector(
                (
                    1.0,
                    0.0,
                    0.0
                )
            )

            lateral = (
                lateral
                - tangent
                * lateral.dot(
                    tangent
                )
            )

            if lateral.length < 0.00001:

                lateral = Vector(
                    (
                        1.0,
                        0.0,
                        0.0
                    )
                )

            lateral.normalize()

            depth = tangent.cross(
                lateral
            )

            if depth.length < 0.00001:

                depth = Vector(
                    (
                        0.0,
                        1.0,
                        0.0
                    )
                )

            depth.normalize()

            return (
                lateral,
                depth
            )

        for section_index, section in enumerate(
            sections
        ):

            center = centers[
                section_index
            ]

            lateral, depth = frame_at(
                section_index
            )

            lateral_radius = section[2]
            depth_radius = section[3]

            for ring_index in range(
                ring_count
            ):

                angle = (
                    math.tau
                    * float(
                        ring_index
                    )
                    / float(
                        ring_count
                    )
                )

                point = (
                    center
                    + lateral
                    * (
                        math.cos(
                            angle
                        )
                        * lateral_radius
                    )
                    + depth
                    * (
                        math.sin(
                            angle
                        )
                        * depth_radius
                    )
                )

                verts.append(
                    tuple(
                        point
                    )
                )

        for section_index in range(
            len(sections) - 1
        ):

            first = (
                section_index
                * ring_count
            )

            second = (
                section_index + 1
            ) * ring_count

            for ring_index in range(
                ring_count
            ):

                next_ring = (
                    ring_index + 1
                ) % ring_count

                faces.append(
                    (
                        first + ring_index,
                        second + ring_index,
                        second + next_ring,
                        first + next_ring
                    )
                )

        root_center_index = len(
            verts
        )

        verts.append(
            tuple(
                centers[0]
            )
        )

        bottom_center_index = len(
            verts
        )

        verts.append(
            tuple(
                centers[-1]
            )
        )

        for ring_index in range(
            ring_count
        ):

            next_ring = (
                ring_index + 1
            ) % ring_count

            faces.append(
                (
                    root_center_index,
                    next_ring,
                    ring_index
                )
            )

            final_start = (
                len(sections) - 1
            ) * ring_count

            faces.append(
                (
                    bottom_center_index,
                    final_start + ring_index,
                    final_start + next_ring
                )
            )

        mesh = bpy.data.meshes.new(
            name + "Mesh"
        )

        mesh.from_pydata(
            verts,
            [],
            faces
        )

        mesh.update()

        obj = bpy.data.objects.new(
            name,
            mesh
        )

        bpy.context.collection.objects.link(
            obj
        )

        obj.data.materials.append(
            coat
        )

        obj.data.materials.append(
            dark_points
        )

        for polygon in obj.data.polygons:

            average_z = (
                sum(
                    obj.data.vertices[
                        vertex_index
                    ].co.z
                    for vertex_index
                    in polygon.vertices
                )
                / float(
                    len(
                        polygon.vertices
                    )
                )
            )

            if average_z < 0.385:

                polygon.material_index = 1

        apply_subdivision(
            obj,
            1
        )

        smooth_object(
            obj
        )

        bind_armature(
            obj,
            group_name
        )

        return obj

