def build_horse_model_v27_base(arm):
    # ========================================================
    # BROKEN KNIGHT HORSE V27
    #
    # HAND-AUTHORED ANATOMICAL CONTROL CAGE
    #
    # V26 RESULT:
    #
    # GOOD:
    # - giant spherical V25 rump was removed
    # - proportions were more controlled
    #
    # BAD:
    # - torso became a rounded log / tube
    # - rump ended like a cylinder cap
    # - neck/body junction was abrupt
    # - round cross-sections erased anatomy
    #
    # V27 CHANGES MODELING METHOD.
    #
    # We preserve the V26 limb blockout for ONE iteration.
    #
    # We completely replace:
    #
    # BODY
    # NECK
    # HEAD
    # EARS
    # EYES
    # MUZZLE DETAILS
    #
    # The new core is one manually authored cage.
    #
    # Every station has different:
    #
    # TOP WIDTH
    # UPPER-RIB WIDTH
    # LOWER-RIB WIDTH
    # BELLY WIDTH
    #
    # and independent:
    #
    # TOP HEIGHT
    # UPPER HEIGHT
    # LOWER HEIGHT
    # BOTTOM HEIGHT
    #
    # Therefore it is NOT a tube.
    #
    # Major semantic regions:
    #
    # nose
    # muzzle
    # nasal bridge
    # cheek
    # poll
    # crest
    # throat
    # neck base
    # withers
    # shoulder
    # chest
    # rib cage
    # belly
    # loin
    # hip
    # croup
    # rump
    # tail dock
    #
    # NO VOXEL REMESH.
    #
    # Catmull-Clark is used once only after the
    # hand-authored shape exists.
    #
    # ========================================================

    build_horse_model_v26_base(
        arm
    )

    # ========================================================
    # MATERIALS
    # ========================================================

    def find_material(
        contains_text
    ):

        for candidate in bpy.data.materials:

            if contains_text.lower() in candidate.name.lower():
                return candidate

        return None

    def make_material(
        name,
        color,
        roughness
    ):

        material = bpy.data.materials.get(
            name
        )

        if material is not None:
            return material

        material = bpy.data.materials.new(
            name=name
        )

        material.diffuse_color = color
        material.use_nodes = True

        bsdf = material.node_tree.nodes.get(
            "Principled BSDF"
        )

        if bsdf is not None:

            if "Base Color" in bsdf.inputs:

                bsdf.inputs[
                    "Base Color"
                ].default_value = color

            if "Roughness" in bsdf.inputs:

                bsdf.inputs[
                    "Roughness"
                ].default_value = roughness

        return material

    coat = find_material(
        "Warm Bay"
    )

    dark_points = find_material(
        "Dark Points"
    )

    hoof_mat = find_material(
        "Hoof"
    )

    if coat is None:

        coat = make_material(
            "Riverwatch V27 Warm Bay",
            (
                0.30,
                0.075,
                0.020,
                1.0
            ),
            0.60
        )

    if dark_points is None:

        dark_points = make_material(
            "Riverwatch V27 Dark Points",
            (
                0.035,
                0.018,
                0.012,
                1.0
            ),
            0.68
        )

    if hoof_mat is None:

        hoof_mat = make_material(
            "Riverwatch V27 Hoof",
            (
                0.16,
                0.135,
                0.115,
                1.0
            ),
            0.74
        )

    eye_mat = make_material(
        "Riverwatch V27 Eye",
        (
            0.007,
            0.005,
            0.004,
            1.0
        ),
        0.28
    )

    # ========================================================
    # HELPERS
    # ========================================================

    def smooth_object(
        obj
    ):

        if obj is None:
            return

        if obj.type != "MESH":
            return

        for polygon in obj.data.polygons:
            polygon.use_smooth = True

    def bind_armature(
        obj,
        group_name
    ):

        obj.parent = arm

        group = obj.vertex_groups.new(
            name=group_name
        )

        group.add(
            list(
                range(
                    len(
                        obj.data.vertices
                    )
                )
            ),
            1.0,
            "REPLACE"
        )

        modifier = obj.modifiers.new(
            "HorseRig",
            "ARMATURE"
        )

        modifier.object = arm

    def apply_subdivision(
        obj,
        levels=1
    ):

        bpy.ops.object.select_all(
            action="DESELECT"
        )

        obj.select_set(
            True
        )

        bpy.context.view_layer.objects.active = obj

        modifier = obj.modifiers.new(
            "V27 Anatomical Surface",
            "SUBSURF"
        )

        modifier.subdivision_type = "CATMULL_CLARK"
        modifier.levels = levels
        modifier.render_levels = levels

        bpy.ops.object.modifier_apply(
            modifier=modifier.name
        )

    # ========================================================
    # DELETE ONLY V26 CORE / HEAD DETAILS
    #
    # KEEP V26:
    #
    # front legs
    # hind legs
    # hooves
    #
    # This isolates whether the V27 BODY METHOD works.
    # ========================================================

    preserved_tokens = (
        "FrontLeftLeg",
        "FrontRightLeg",
        "HindLeftLeg",
        "HindRightLeg",
        "FrontLeftHoof",
        "FrontRightHoof",
        "HindLeftHoof",
        "HindRightHoof",
    )

    delete_targets = []

    for obj in list(
        bpy.data.objects
    ):

        if (
            obj.type == "MESH"
            and obj.name.startswith(
                "RiverwatchV26"
            )
        ):

            if any(
                token in obj.name
                for token in preserved_tokens
            ):

                continue

            delete_targets.append(
                obj
            )

    print(
        "V27_DELETE_V26_CORE_MESHES",
        len(
            delete_targets
        )
    )

    for obj in delete_targets:

        if obj.name in bpy.data.objects:

            bpy.data.objects.remove(
                obj,
                do_unlink=True
            )

