    # ========================================================
    # BUILD ONE CONTINUOUS CAGE
    # ========================================================

    ring_count = 8

    verts = []
    faces = []

    for station in stations:

        (
            y,
            top_z,
            upper_z,
            lower_z,
            bottom_z,
            top_width,
            upper_width,
            lower_width,
            bottom_width
        ) = station

        ring = [

            (
                -top_width,
                y,
                top_z
            ),

            (
                top_width,
                y,
                top_z
            ),

            (
                upper_width,
                y,
                upper_z
            ),

            (
                lower_width,
                y,
                lower_z
            ),

            (
                bottom_width,
                y,
                bottom_z
            ),

            (
                -bottom_width,
                y,
                bottom_z
            ),

            (
                -lower_width,
                y,
                lower_z
            ),

            (
                -upper_width,
                y,
                upper_z
            ),
        ]

        verts.extend(
            ring
        )

    # ========================================================
    # CONNECT STATIONS
    # ========================================================

    for station_index in range(
        len(stations) - 1
    ):

        current_start = (
            station_index
            * ring_count
        )

        next_start = (
            station_index + 1
        ) * ring_count

        for ring_index in range(
            ring_count
        ):

            next_ring_index = (
                ring_index + 1
            ) % ring_count

            faces.append(
                (
                    current_start + ring_index,
                    next_start + ring_index,
                    next_start + next_ring_index,
                    current_start + next_ring_index
                )
            )

    # Nose cap.
    faces.append(
        tuple(
            reversed(
                range(
                    0,
                    ring_count
                )
            )
        )
    )

    # Tiny tail-dock cap.
    final_start = (
        len(stations) - 1
    ) * ring_count

    faces.append(
        tuple(
            range(
                final_start,
                final_start + ring_count
            )
        )
    )

    cage_mesh = bpy.data.meshes.new(
        "RiverwatchV27AnatomicalControlCageMesh"
    )

    cage_mesh.from_pydata(
        verts,
        [],
        faces
    )

    cage_mesh.update()

    cage = bpy.data.objects.new(
        "RiverwatchV27AnatomicalControlCage",
        cage_mesh
    )

    bpy.context.collection.objects.link(
        cage
    )

    cage.data.materials.append(
        coat
    )

    # ========================================================
    # SUBDIVIDE ONCE
    #
    # No remesh afterward.
    #
    # This preserves the intentionally shaped planes.
    # ========================================================

    apply_subdivision(
        cage,
        1
    )

    smooth_object(
        cage
    )

    bind_armature(
        cage,
        "body"
    )

