    # ========================================================
    # V26 LEG POLISH
    #
    # Keep the landmark positions.
    #
    # Only refine silhouette while V27 tests the new body.
    # ========================================================

    def refine_front_leg(
        obj_name,
        center_x
    ):

        obj = bpy.data.objects.get(
            obj_name
        )

        if obj is None:
            return

        for vertex in obj.data.vertices:

            z = vertex.co.z

            local_x = (
                vertex.co.x
                - center_x
            )

            # Upper forearm gets slightly stronger.
            if (
                z > 0.70
                and z < 1.05
            ):

                vertex.co.x = (
                    center_x
                    + local_x
                    * 1.035
                )

            # Knee is visible.
            elif (
                z > 0.48
                and z <= 0.62
            ):

                vertex.co.x = (
                    center_x
                    + local_x
                    * 1.040
                )

            # Cannon slimmer.
            elif (
                z > 0.21
                and z <= 0.47
            ):

                vertex.co.x = (
                    center_x
                    + local_x
                    * 0.940
                )

    def refine_hind_leg(
        obj_name,
        center_x
    ):

        obj = bpy.data.objects.get(
            obj_name
        )

        if obj is None:
            return

        for vertex in obj.data.vertices:

            z = vertex.co.z

            local_x = (
                vertex.co.x
                - center_x
            )

            # Fuller upper thigh.
            if z > 0.92:

                vertex.co.x = (
                    center_x
                    + local_x
                    * 1.035
                )

            # Slightly more restrained stifle.
            elif (
                z > 0.76
                and z <= 0.92
            ):

                vertex.co.y += 0.012

            # Hock stands out.
            elif (
                z > 0.48
                and z <= 0.61
            ):

                vertex.co.x = (
                    center_x
                    + local_x
                    * 1.045
                )

                vertex.co.y += 0.012

            # Long slim hind cannon.
            elif (
                z > 0.21
                and z <= 0.47
            ):

                vertex.co.x = (
                    center_x
                    + local_x
                    * 0.930
                )

                target_y = 0.565

                vertex.co.y = (
                    target_y
                    + (
                        vertex.co.y
                        - target_y
                    )
                    * 0.90
                )

    refine_front_leg(
        "RiverwatchV26FrontLeftLeg",
        -0.285
    )

    refine_front_leg(
        "RiverwatchV26FrontRightLeg",
        0.285
    )

    refine_hind_leg(
        "RiverwatchV26HindLeftLeg",
        -0.315
    )

    refine_hind_leg(
        "RiverwatchV26HindRightLeg",
        0.315
    )

    # ========================================================
    # RENAME PRESERVED V26 LEGS / HOOFS
    # ========================================================

    for obj in list(
        bpy.context.scene.objects
    ):

        if obj.name.startswith(
            "RiverwatchV26"
        ):

            obj.name = obj.name.replace(
                "RiverwatchV26",
                "RiverwatchV27",
                1
            )

    for material in bpy.data.materials:

        if material.name.startswith(
            "Riverwatch V26"
        ):

            material.name = material.name.replace(
                "Riverwatch V26",
                "Riverwatch V27",
                1
            )

