    # ========================================================
    # HOOF BUILDER
    # ========================================================

    def build_hoof(
        name,
        center_x,
        heel_y,
        toe_y,
        group_name,
        rear=False
    ):

        if rear:

            heel_width = 0.062
            toe_width = 0.086

        else:

            heel_width = 0.064
            toe_width = 0.091

        heel_top = 0.105
        toe_top = 0.070

        heel_bottom = 0.030
        toe_bottom = 0.018

        verts = [

            (
                center_x - heel_width,
                heel_y,
                heel_top
            ),

            (
                center_x + heel_width,
                heel_y,
                heel_top
            ),

            (
                center_x - toe_width,
                toe_y,
                toe_top
            ),

            (
                center_x + toe_width,
                toe_y,
                toe_top
            ),

            (
                center_x - heel_width,
                heel_y,
                heel_bottom
            ),

            (
                center_x + heel_width,
                heel_y,
                heel_bottom
            ),

            (
                center_x - toe_width,
                toe_y,
                toe_bottom
            ),

            (
                center_x + toe_width,
                toe_y,
                toe_bottom
            ),
        ]

        faces = [

            (
                0,
                1,
                3,
                2
            ),

            (
                6,
                7,
                5,
                4
            ),

            (
                0,
                2,
                6,
                4
            ),

            (
                1,
                5,
                7,
                3
            ),

            (
                0,
                4,
                5,
                1
            ),

            (
                2,
                3,
                7,
                6
            ),
        ]

        mesh = bpy.data.meshes.new(
            name + "Mesh"
        )

        mesh.from_pydata(
            verts,
            [],
            faces
        )

        mesh.update()

        obj = bpy.data.objects.new(
            name,
            mesh
        )

        bpy.context.collection.objects.link(
            obj
        )

        obj.data.materials.append(
            hoof_mat
        )

        bpy.ops.object.select_all(
            action="DESELECT"
        )

        obj.select_set(
            True
        )

        bpy.context.view_layer.objects.active = obj

        bevel = obj.modifiers.new(
            "V29 Hoof Edge",
            "BEVEL"
        )

        bevel.width = 0.009
        bevel.segments = 3

        bpy.ops.object.modifier_apply(
            modifier=bevel.name
        )

        smooth_object(
            obj
        )

        bind_armature(
            obj,
            group_name
        )

        return obj

