    # ========================================================
    # LIMB BUILDER
    #
    # IMPORTANT:
    #
    # NO TOP CAP.
    #
    # The upper limb penetrates into the body.
    #
    # V30's visible flat cap / seam at shoulder should
    # therefore disappear.
    # ========================================================

    limb_ring = [

        (
            1.00,
            0.00
        ),

        (
            0.70,
            0.72
        ),

        (
            0.00,
            1.00
        ),

        (
            -0.70,
            0.72
        ),

        (
            -1.00,
            0.00
        ),

        (
            -0.70,
            -0.72
        ),

        (
            0.00,
            -1.00
        ),

        (
            0.70,
            -0.72
        ),
    ]

    def build_limb(
        name,
        center_x,
        limb_sections,
        group_name
    ):

        centers = [

            Vector(
                (
                    center_x,
                    section[0],
                    section[1]
                )
            )

            for section in limb_sections
        ]

        ring_total = len(
            limb_ring
        )

        vertices = []
        polygons = []

        def frame_at(index):

            if index == 0:

                tangent = (
                    centers[1]
                    - centers[0]
                )

            elif index == len(
                centers
            ) - 1:

                tangent = (
                    centers[-1]
                    - centers[-2]
                )

            else:

                tangent = (
                    centers[
                        index + 1
                    ]
                    - centers[
                        index - 1
                    ]
                )

            if tangent.length < 0.000001:

                tangent = Vector(
                    (
                        0.0,
                        0.0,
                        -1.0
                    )
                )

            tangent.normalize()

            lateral = Vector(
                (
                    1.0,
                    0.0,
                    0.0
                )
            )

            lateral = (
                lateral
                - tangent
                * lateral.dot(
                    tangent
                )
            )

            if lateral.length < 0.000001:

                lateral = Vector(
                    (
                        1.0,
                        0.0,
                        0.0
                    )
                )

            lateral.normalize()

            depth = tangent.cross(
                lateral
            )

            if depth.length < 0.000001:

                depth = Vector(
                    (
                        0.0,
                        1.0,
                        0.0
                    )
                )

            depth.normalize()

            return (
                lateral,
                depth
            )

        for index, section in enumerate(
            limb_sections
        ):

            center = centers[
                index
            ]

            width = section[2]
            depth_radius = section[3]

            lateral, depth = frame_at(
                index
            )

            for (
                profile_x,
                profile_y
            ) in limb_ring:

                point = (
                    center
                    + lateral
                    * (
                        profile_x
                        * width
                    )
                    + depth
                    * (
                        profile_y
                        * depth_radius
                    )
                )

                vertices.append(
                    tuple(
                        point
                    )
                )

        for section_index in range(
            len(limb_sections) - 1
        ):

            current = (
                section_index
                * ring_total
            )

            following = (
                section_index + 1
            ) * ring_total

            for ring_index in range(
                ring_total
            ):

                next_ring = (
                    ring_index + 1
                ) % ring_total

                polygons.append(
                    (
                        current + ring_index,
                        following + ring_index,
                        following + next_ring,
                        current + next_ring
                    )
                )

        # NO ROOT CAP.

        # Bottom cap only.
        bottom_center = len(
            vertices
        )

        vertices.append(
            tuple(
                centers[-1]
            )
        )

        final_start = (
            len(limb_sections) - 1
        ) * ring_total

        for ring_index in range(
            ring_total
        ):

            next_ring = (
                ring_index + 1
            ) % ring_total

            polygons.append(
                (
                    bottom_center,
                    final_start + ring_index,
                    final_start + next_ring
                )
            )

        mesh = bpy.data.meshes.new(
            name + "Mesh"
        )

        mesh.from_pydata(
            vertices,
            [],
            polygons
        )

        mesh.update()

        obj = bpy.data.objects.new(
            name,
            mesh
        )

        bpy.context.collection.objects.link(
            obj
        )

        obj.data.materials.append(
            coat
        )

        obj.data.materials.append(
            dark_points
        )

        for polygon in obj.data.polygons:

            average_z = (
                sum(
                    obj.data.vertices[
                        vertex_index
                    ].co.z
                    for vertex_index
                    in polygon.vertices
                )
                / float(
                    len(
                        polygon.vertices
                    )
                )
            )

            if average_z < 0.375:

                polygon.material_index = 1

        subdivide_once(
            obj
        )

        smooth_object(
            obj
        )

        bind_armature(
            obj,
            group_name
        )

        return obj

