    # ========================================================
    # LARGE NATURALLY ANGLED HOOF
    # ========================================================

    def build_hoof(
        name,
        center_x,
        heel_y,
        toe_y,
        group_name,
        rear=False
    ):

        if rear:

            heel_width = 0.075
            toe_width = 0.110

        else:

            heel_width = 0.078
            toe_width = 0.115

        heel_top = 0.115
        toe_top = 0.070

        heel_bottom = 0.030
        toe_bottom = 0.018

        vertices = [

            (
                center_x - heel_width,
                heel_y,
                heel_top
            ),

            (
                center_x + heel_width,
                heel_y,
                heel_top
            ),

            (
                center_x - toe_width,
                toe_y,
                toe_top
            ),

            (
                center_x + toe_width,
                toe_y,
                toe_top
            ),

            (
                center_x - heel_width,
                heel_y,
                heel_bottom
            ),

            (
                center_x + heel_width,
                heel_y,
                heel_bottom
            ),

            (
                center_x - toe_width,
                toe_y,
                toe_bottom
            ),

            (
                center_x + toe_width,
                toe_y,
                toe_bottom
            ),
        ]

        faces = [

            (
                0,
                1,
                3,
                2
            ),

            (
                6,
                7,
                5,
                4
            ),

            (
                0,
                2,
                6,
                4
            ),

            (
                1,
                5,
                7,
                3
            ),

            (
                0,
                4,
                5,
                1
            ),

            (
                2,
                3,
                7,
                6
            ),
        ]

        hoof = create_mesh_object(
            name,
            vertices,
            faces,
            hoof_mat
        )

        deselect_all()

        hoof.select_set(
            True
        )

        bpy.context.view_layer.objects.active = hoof

        bevel = hoof.modifiers.new(
            "V33 Hoof Bevel",
            "BEVEL"
        )

        bevel.width = 0.014
        bevel.segments = 3

        bpy.ops.object.modifier_apply(
            modifier=bevel.name
        )

        smooth_object(
            hoof
        )

        bind_armature(
            hoof,
            group_name
        )

        return hoof

