    # ========================================================
    # SIMPLE ELLIPSOID
    # ========================================================

    def add_ellipsoid(
        name,
        location,
        scale,
        material,
        group_name="body",
        segments=24,
        rings=14
    ):

        bpy.ops.mesh.primitive_uv_sphere_add(
            segments=segments,
            ring_count=rings,
            location=location
        )

        obj = bpy.context.object

        obj.name = name

        obj.scale = Vector(
            scale
        )

        bpy.ops.object.transform_apply(
            location=False,
            rotation=False,
            scale=True
        )

        obj.data.materials.append(
            material
        )

        smooth_object(
            obj
        )

        bind_armature(
            obj,
            group_name
        )

        return obj

