    def add_beveled_box(
        name,
        location,
        dimensions,
        material,
        bevel_width=0.025,
        group_name="body"
    ):

        bpy.ops.mesh.primitive_cube_add(
            location=location
        )

        obj = bpy.context.object

        obj.name = name

        obj.scale = Vector(
            (
                dimensions[0] * 0.5,
                dimensions[1] * 0.5,
                dimensions[2] * 0.5
            )
        )

        bpy.ops.object.transform_apply(
            location=False,
            rotation=False,
            scale=True
        )

        obj.data.materials.append(
            material
        )

        deselect_all()

        obj.select_set(
            True
        )

        bpy.context.view_layer.objects.active = obj

        bevel = obj.modifiers.new(
            "V33 Rounded Leather",
            "BEVEL"
        )

        bevel.width = bevel_width
        bevel.segments = 3

        bpy.ops.object.modifier_apply(
            modifier=bevel.name
        )

        smooth_object(
            obj
        )

        bind_armature(
            obj,
            group_name
        )

        return obj

    # ========================================================
