def build_horse_model_v34_base(arm):

    import bpy
    import math

    from mathutils import Vector

    # ========================================================
    # BROKEN KNIGHT HORSE V34
    #
    # HARD REFERENCE-MATCH CORRECTION
    #
    # SOURCE OF TRUTH:
    #
    # Fantasy Riding / Pack Horse reference sheet.
    #
    # V33 successes:
    #
    # - complete tack returned
    # - obvious horse equipment/color identity returned
    # - head details improved
    #
    # V33 failures versus ACTUAL IMAGE:
    #
    # - head / nose still too long
    # - head carriage too horizontal
    # - neck too long and too straight
    # - neck lacks the heavy curved reference silhouette
    # - shoulder / chest too weak
    # - torso too narrow
    # - hindquarter not powerful enough
    # - front legs too tubular
    # - hind leg still crouched
    # - mane barely visible
    # - tail too simple
    # - blanket far too boxy / oversized
    # - saddle looks like stacked blobs
    # - bags too large and cubic
    #
    # V34 retains ONLY the V33 continuous body mesh.
    #
    # Everything attached to it is deleted and rebuilt.
    #
    # ========================================================

    build_horse_model_v33_base(
        arm
    )

    # ========================================================
    # MATERIAL HELPERS
    # ========================================================

    def get_material(
        name,
        fallback_color,
        roughness=0.6,
        metallic=0.0
    ):

        mat = bpy.data.materials.get(
            name
        )

        if mat is None:

            mat = bpy.data.materials.new(
                name=name
            )

        mat.diffuse_color = fallback_color
        mat.use_nodes = True

        bsdf = mat.node_tree.nodes.get(
            "Principled BSDF"
        )

        if bsdf is not None:

            if "Base Color" in bsdf.inputs:

                bsdf.inputs[
                    "Base Color"
                ].default_value = fallback_color

            if "Roughness" in bsdf.inputs:

                bsdf.inputs[
                    "Roughness"
                ].default_value = roughness

            if "Metallic" in bsdf.inputs:

                bsdf.inputs[
                    "Metallic"
                ].default_value = metallic

        return mat

    coat = get_material(
        "Riverwatch V33 Warm Bay",
        (
            0.235,
            0.060,
            0.018,
            1.0
        ),
        0.61
    )

    coat.name = "Riverwatch V34 Warm Bay"

    dark = get_material(
        "Riverwatch V33 Dark Mane Points",
        (
            0.018,
            0.010,
            0.007,
            1.0
        ),
        0.72
    )

    dark.name = "Riverwatch V34 Dark Mane Points"

    muzzle_mat = get_material(
        "Riverwatch V33 Muzzle",
        (
            0.085,
            0.067,
            0.060,
            1.0
        ),
        0.75
    )

    muzzle_mat.name = "Riverwatch V34 Muzzle"

    hoof_mat = get_material(
        "Riverwatch V33 Hoof",
        (
            0.080,
            0.067,
            0.058,
            1.0
        ),
        0.78
    )

    hoof_mat.name = "Riverwatch V34 Hoof"

    eye_mat = get_material(
        "Riverwatch V33 Eye",
        (
            0.003,
            0.002,
            0.001,
            1.0
        ),
        0.22
    )

    eye_mat.name = "Riverwatch V34 Eye"

    leather = get_material(
        "Riverwatch V33 Leather",
        (
            0.115,
            0.045,
            0.022,
            1.0
        ),
        0.68
    )

    leather.name = "Riverwatch V34 Leather"

    leather_dark = get_material(
        "Riverwatch V33 Dark Leather",
        (
            0.060,
            0.024,
            0.014,
            1.0
        ),
        0.72
    )

    leather_dark.name = "Riverwatch V34 Dark Leather"

    blue = get_material(
        "Riverwatch V33 Royal Blue Blanket",
        (
            0.025,
            0.080,
            0.220,
            1.0
        ),
        0.62
    )

    blue.name = "Riverwatch V34 Royal Blue Blanket"

    gold = get_material(
        "Riverwatch V33 Brass Gold",
        (
            0.53,
            0.30,
            0.065,
            1.0
        ),
        0.38,
        0.52
    )

    gold.name = "Riverwatch V34 Brass Gold"

    metal = get_material(
        "Riverwatch V33 Iron",
        (
            0.15,
            0.15,
            0.145,
            1.0
        ),
        0.32,
        0.74
    )

    metal.name = "Riverwatch V34 Iron"

    # ========================================================
    # HELPERS
    # ========================================================

    def deselect():

        bpy.ops.object.select_all(
            action="DESELECT"
        )

    def smooth(
        obj
    ):

        if obj is None:
            return

        if obj.type != "MESH":
            return

        for polygon in obj.data.polygons:

            polygon.use_smooth = True

    def bind(
        obj,
        group_name
    ):

        obj.parent = arm

        group = obj.vertex_groups.new(
            name=group_name
        )

        group.add(
            list(
                range(
                    len(
                        obj.data.vertices
                    )
                )
            ),
            1.0,
            "REPLACE"
        )

        modifier = obj.modifiers.new(
            "HorseRig",
            "ARMATURE"
        )

        modifier.object = arm

    def subdivide(
        obj
    ):

        deselect()

        obj.select_set(
            True
        )

        bpy.context.view_layer.objects.active = obj

        modifier = obj.modifiers.new(
            "V34 Surface",
            "SUBSURF"
        )

        modifier.subdivision_type = "CATMULL_CLARK"
        modifier.levels = 1
        modifier.render_levels = 1

        bpy.ops.object.modifier_apply(
            modifier=modifier.name
        )

    def mesh_object(
        name,
        vertices,
        faces,
        material
    ):

        mesh = bpy.data.meshes.new(
            name + "Mesh"
        )

        mesh.from_pydata(
            vertices,
            [],
            faces
        )

        mesh.update()

        obj = bpy.data.objects.new(
            name,
            mesh
        )

        bpy.context.collection.objects.link(
            obj
        )

        obj.data.materials.append(
            material
        )

        return obj

    def sphere_part(
        name,
        location,
        scale,
        material,
        group_name="body",
        segments=24,
        rings=14
    ):

        bpy.ops.mesh.primitive_uv_sphere_add(
            segments=segments,
            ring_count=rings,
            location=location
        )

        obj = bpy.context.object

        obj.name = name

        obj.scale = Vector(
            scale
        )

        bpy.ops.object.transform_apply(
            location=False,
            rotation=False,
            scale=True
        )

        obj.data.materials.append(
            material
        )

        smooth(
            obj
        )

        bind(
            obj,
            group_name
        )

        return obj

    def beveled_box(
        name,
        location,
        dimensions,
        material,
        bevel_amount=0.018,
        group_name="body"
    ):

        bpy.ops.mesh.primitive_cube_add(
            location=location
        )

        obj = bpy.context.object

        obj.name = name

        obj.scale = Vector(
            (
                dimensions[0] * 0.5,
                dimensions[1] * 0.5,
                dimensions[2] * 0.5
            )
        )

        bpy.ops.object.transform_apply(
            location=False,
            rotation=False,
            scale=True
        )

        obj.data.materials.append(
            material
        )

        if bevel_amount > 0.0:

            deselect()

            obj.select_set(
                True
            )

            bpy.context.view_layer.objects.active = obj

            modifier = obj.modifiers.new(
                "V34 Edge",
                "BEVEL"
            )

            modifier.width = bevel_amount
            modifier.segments = 3

            bpy.ops.object.modifier_apply(
                modifier=modifier.name
            )

        smooth(
            obj
        )

        bind(
            obj,
            group_name
        )

        return obj

    def curve_mesh(
        name,
        points,
        material,
        thickness,
        group_name="body"
    ):

        curve_data = bpy.data.curves.new(
            name=name + "Curve",
            type="CURVE"
        )

        curve_data.dimensions = "3D"
        curve_data.resolution_u = 3
        curve_data.bevel_depth = thickness
        curve_data.bevel_resolution = 2

        spline = curve_data.splines.new(
            "BEZIER"
        )

        spline.bezier_points.add(
            len(
                points
            ) - 1
        )

        for index, point in enumerate(
            points
        ):

            bezier = spline.bezier_points[
                index
            ]

            bezier.co = point
            bezier.handle_left_type = "AUTO"
            bezier.handle_right_type = "AUTO"

        obj = bpy.data.objects.new(
            name,
            curve_data
        )

        bpy.context.collection.objects.link(
            obj
        )

        obj.data.materials.append(
            material
        )

        deselect()

        obj.select_set(
            True
        )

        bpy.context.view_layer.objects.active = obj

        bpy.ops.object.convert(
            target="MESH"
        )

        result = bpy.context.object

        result.name = name

        smooth(
            result
        )

        bind(
            result,
            group_name
        )

        return result

    def torus_part(
        name,
        location,
        rotation,
        major_radius,
        minor_radius,
        material,
        scale=(
            1.0,
            1.0,
            1.0
        ),
        group_name="body"
    ):

        bpy.ops.mesh.primitive_torus_add(
            major_radius=major_radius,
            minor_radius=minor_radius,
            major_segments=24,
            minor_segments=8,
            location=location,
            rotation=rotation
        )

        obj = bpy.context.object

        obj.name = name

        obj.scale = Vector(
            scale
        )

        bpy.ops.object.transform_apply(
            location=False,
            rotation=False,
            scale=True
        )

        obj.data.materials.append(
            material
        )

        smooth(
            obj
        )

        bind(
            obj,
            group_name
        )

        return obj

    # ========================================================
    # KEEP ONLY V33 BODY
    # ========================================================

    body = bpy.data.objects.get(
        "RiverwatchV33ReferenceBody"
    )

    if body is None:

        raise RuntimeError(
            "V34 could not locate RiverwatchV33ReferenceBody"
        )

    delete_targets = []

    for obj in list(
        bpy.data.objects
    ):

        if not obj.name.startswith(
            "RiverwatchV33"
        ):
            continue

        if obj == body:
            continue

        delete_targets.append(
            obj
        )

    print(
        "V34_DELETE_V33_ATTACHED_OBJECTS",
        len(
            delete_targets
        )
    )

    for obj in delete_targets:

        if obj.name in bpy.data.objects:

            bpy.data.objects.remove(
                obj,
                do_unlink=True
            )

    # ========================================================
    # BODY WARP DIRECTLY FROM REFERENCE DIFFERENCES
    # ========================================================

    HEAD_PIVOT_Y = -0.820
    HEAD_PIVOT_Z = 1.775

    HEAD_ANGLE = math.radians(
        8.0
    )

    COS_A = math.cos(
        HEAD_ANGLE
    )

    SIN_A = math.sin(
        HEAD_ANGLE
    )

    for vertex in body.data.vertices:

        x = vertex.co.x
        y = vertex.co.y
        z = vertex.co.z

        nx = x
        ny = y
        nz = z

        # ----------------------------------------------------
        # TORSO LENGTH
        #
        # Current V33 torso reads long/light.
        #
        # Compress shoulder-to-rear by 6%.
        # ----------------------------------------------------

        if y > -0.350:

            ny = (
                -0.350
                + (
                    y + 0.350
                )
                * 0.940
            )

        # ----------------------------------------------------
        # NECK
        #
        # Reference neck is much steeper, shorter and fuller.
        # ----------------------------------------------------

        if (
            y <= -0.430
            and y >= -0.900
        ):

            neck_t = max(
                0.0,
                min(
                    1.0,
                    (
                        -y - 0.430
                    )
                    / 0.470
                )
            )

            ny = (
                -0.430
                + (
                    y + 0.430
                )
                * 0.840
            )

            # Very substantial reference neck.
            nx *= (
                1.27
                - 0.09
                * neck_t
            )

            # Raise crest.
            if z > 1.62:

                nz += (
                    0.050
                    * (
                        1.0
                        - abs(
                            neck_t - 0.45
                        )
                    )
                )

            # Pull throat inward/back.
            if z < 1.52:

                ny += (
                    0.040
                    * (
                        1.0 - neck_t
                    )
                )

                nx *= 0.965

        # ----------------------------------------------------
        # HEAD
        #
        # Shorter face and downward horse carriage.
        # ----------------------------------------------------

        if y < -0.900:

            head_progress = max(
                0.0,
                min(
                    1.0,
                    (
                        -y - 0.900
                    )
                    / 0.420
                )
            )

            # Head follows new poll location.
            ny = (
                HEAD_PIVOT_Y
                + (
                    y + 0.900
                )
                * 0.880
            )

            # Broader cheek.
            cheek = math.exp(
                -(
                    (
                        y + 1.015
                    )
                    / 0.105
                ) ** 2
            )

            nx *= (
                1.02
                + 0.11
                * cheek
                - 0.05
                * head_progress
            )

            dy = (
                ny
                - HEAD_PIVOT_Y
            )

            dz = (
                nz
                - HEAD_PIVOT_Z
            )

            rotated_y = (
                dy * COS_A
                - dz * SIN_A
            )

            rotated_z = (
                dy * SIN_A
                + dz * COS_A
            )

            ny = (
                HEAD_PIVOT_Y
                + rotated_y
            )

            nz = (
                HEAD_PIVOT_Z
                + rotated_z
            )

        # ----------------------------------------------------
        # WITHERS / SHOULDER
        # ----------------------------------------------------

        shoulder = math.exp(
            -(
                (
                    y + 0.300
                )
                / 0.180
            ) ** 2
        )

        if shoulder > 0.03:

            if z > 1.18:

                nx *= (
                    1.0
                    + 0.10
                    * shoulder
                )

            if z < 1.18:

                depth = max(
                    0.0,
                    min(
                        1.0,
                        (
                            1.18 - z
                        )
                        / 0.42
                    )
                )

                nz -= (
                    0.075
                    * depth
                    * shoulder
                )

        # More defined wither peak.
        wither = math.exp(
            -(
                (
                    y + 0.430
                )
                / 0.100
            ) ** 2
        )

        if z > 1.52:

            nz += (
                0.032
                * wither
            )

        # ----------------------------------------------------
        # BARREL
        #
        # Fuller ribs, but controlled belly.
        # ----------------------------------------------------

        barrel = math.exp(
            -(
                (
                    y - 0.130
                )
                / 0.390
            ) ** 2
        )

        if barrel > 0.03:

            if (
                z > 0.95
                and z < 1.48
            ):

                nx *= (
                    1.0
                    + 0.065
                    * barrel
                )

            if z < 1.02:

                belly_depth = max(
                    0.0,
                    min(
                        1.0,
                        (
                            1.02 - z
                        )
                        / 0.30
                    )
                )

                nz -= (
                    0.045
                    * barrel
                    * belly_depth
                )

        # ----------------------------------------------------
        # LOIN / CROUP / HINDQUARTER
        # ----------------------------------------------------

        croup = math.exp(
            -(
                (
                    y - 0.760
                )
                / 0.245
            ) ** 2
        )

        if croup > 0.03:

            nx *= (
                1.0
                + 0.095
                * croup
            )

            # Round upper croup.
            if z > 1.32:

                nz += (
                    0.065
                    * croup
                )

            # Fuller lower quarter.
            if (
                z > 1.00
                and z < 1.30
            ):

                nx *= (
                    1.0
                    + 0.035
                    * croup
                )

        vertex.co.x = nx
        vertex.co.y = ny
        vertex.co.z = nz

    body.name = "RiverwatchV34ReferenceBody"

