    # ========================================================
    # BASIC HELPERS
    # ========================================================

    def deselect():

        bpy.ops.object.select_all(
            action="DESELECT"
        )

    def smooth(
        obj
    ):

        if obj is None:
            return

        if obj.type != "MESH":
            return

        for polygon in obj.data.polygons:
            polygon.use_smooth = True

    def bind(
        obj,
        group_name
    ):

        obj.parent = arm

        group = obj.vertex_groups.new(
            name=group_name
        )

        group.add(
            list(
                range(
                    len(
                        obj.data.vertices
                    )
                )
            ),
            1.0,
            "REPLACE"
        )

        modifier = obj.modifiers.new(
            "HorseRig",
            "ARMATURE"
        )

        modifier.object = arm

    def create_mesh(
        name,
        vertices,
        faces,
        material
    ):

        mesh = bpy.data.meshes.new(
            name + "Mesh"
        )

        mesh.from_pydata(
            vertices,
            [],
            faces
        )

        mesh.update()

        obj = bpy.data.objects.new(
            name,
            mesh
        )

        bpy.context.collection.objects.link(
            obj
        )

        obj.data.materials.append(
            material
        )

        return obj

    def subdivide(
        obj,
        levels
    ):

        deselect()

        obj.select_set(
            True
        )

        bpy.context.view_layer.objects.active = obj

        modifier = obj.modifiers.new(
            "V42 Subdivision",
            "SUBSURF"
        )

        modifier.subdivision_type = "CATMULL_CLARK"
        modifier.levels = levels
        modifier.render_levels = levels

        bpy.ops.object.modifier_apply(
            modifier=modifier.name
        )

    def bevel(
        obj,
        width,
        segments=3
    ):

        deselect()

        obj.select_set(
            True
        )

        bpy.context.view_layer.objects.active = obj

        modifier = obj.modifiers.new(
            "V42 Bevel",
            "BEVEL"
        )

        modifier.width = width
        modifier.segments = segments

        bpy.ops.object.modifier_apply(
            modifier=modifier.name
        )

    def ellipsoid(
        name,
        location,
        scale,
        material,
        group_name
    ):

        bpy.ops.mesh.primitive_uv_sphere_add(
            segments=28,
            ring_count=18,
            location=location
        )

        obj = bpy.context.object

        obj.name = name
        obj.scale = Vector(scale)

        bpy.ops.object.transform_apply(
            location=False,
            rotation=False,
            scale=True
        )

        obj.data.materials.append(
            material
        )

        smooth(
            obj
        )

        bind(
            obj,
            group_name
        )

        return obj

    def rounded_box(
        name,
        location,
        dimensions,
        material,
        group_name,
        bevel_width=0.025
    ):

        bpy.ops.mesh.primitive_cube_add(
            location=location
        )

        obj = bpy.context.object

        obj.name = name

        obj.scale = Vector(
            (
                dimensions[0] * 0.5,
                dimensions[1] * 0.5,
                dimensions[2] * 0.5
            )
        )

        bpy.ops.object.transform_apply(
            location=False,
            rotation=False,
            scale=True
        )

        obj.data.materials.append(
            material
        )

        bevel(
            obj,
            bevel_width,
            4
        )

        smooth(
            obj
        )

        bind(
            obj,
            group_name
        )

        return obj

    def curve_mesh(
        name,
        points,
        material,
        thickness,
        group_name,
        resolution=3
    ):

        curve_data = bpy.data.curves.new(
            name=name + "Curve",
            type="CURVE"
        )

        curve_data.dimensions = "3D"
        curve_data.resolution_u = resolution
        curve_data.bevel_depth = thickness
        curve_data.bevel_resolution = 3

        spline = curve_data.splines.new(
            "BEZIER"
        )

        spline.bezier_points.add(
            len(points) - 1
        )

        for index, point in enumerate(
            points
        ):

            bp = spline.bezier_points[
                index
            ]

            bp.co = point
            bp.handle_left_type = "AUTO"
            bp.handle_right_type = "AUTO"

        obj = bpy.data.objects.new(
            name,
            curve_data
        )

        bpy.context.collection.objects.link(
            obj
        )

        obj.data.materials.append(
            material
        )

        deselect()

        obj.select_set(
            True
        )

        bpy.context.view_layer.objects.active = obj

        bpy.ops.object.convert(
            target="MESH"
        )

        result = bpy.context.object

        result.name = name

        smooth(
            result
        )

        bind(
            result,
            group_name
        )

        return result

    def prism_from_side(
        name,
        outline,
        x_min,
        x_max,
        material,
        group_name,
        bevel_width=0.0
    ):

        count = len(
            outline
        )

        vertices = []

        for y, z in outline:

            vertices.append(
                (
                    x_min,
                    y,
                    z
                )
            )

        for y, z in outline:

            vertices.append(
                (
                    x_max,
                    y,
                    z
                )
            )

        faces = []

        faces.append(
            tuple(
                reversed(
                    range(count)
                )
            )
        )

        faces.append(
            tuple(
                range(
                    count,
                    count * 2
                )
            )
        )

        for index in range(
            count
        ):

            nxt = (
                index + 1
            ) % count

            faces.append(
                (
                    index,
                    nxt,
                    count + nxt,
                    count + index
                )
            )

        obj = create_mesh(
            name,
            vertices,
            faces,
            material
        )

        if bevel_width > 0.0:

            bevel(
                obj,
                bevel_width,
                3
            )

        smooth(
            obj
        )

        bind(
            obj,
            group_name
        )

        return obj

    def torus_part(
        name,
        location,
        major_radius,
        minor_radius,
        material,
        group_name
    ):

        bpy.ops.mesh.primitive_torus_add(
            major_radius=major_radius,
            minor_radius=minor_radius,
            major_segments=24,
            minor_segments=8,
            location=location,
            rotation=(
                0.0,
                math.radians(90.0),
                0.0
            )
        )

        obj = bpy.context.object

        obj.name = name
        obj.data.materials.append(material)

        smooth(obj)
        bind(obj, group_name)

        return obj

    # ========================================================
    # GENERIC ELLIPTICAL LOFT
    #
    # section:
    #
    # y
    # z
    # x radius
    # vertical radius
    #
    # oriented=True rotates each cross-section to follow the
    # local centerline direction.
    #
    # ========================================================

    loft_profile = [

        (1.00, 0.00),
        (0.707, 0.707),
        (0.00, 1.00),
        (-0.707, 0.707),
        (-1.00, 0.00),
        (-0.707, -0.707),
        (0.00, -1.00),
        (0.707, -0.707),
    ]

    def build_loft(
        name,
        sections,
        material,
        group_name,
        oriented,
        subdivision=1
    ):

        centers = [

            Vector(
                (
                    0.0,
                    section[0],
                    section[1]
                )
            )

            for section in sections
        ]

        vertices = []
        faces = []

        ring = len(
            loft_profile
        )

        def frame_at(
            index
        ):

            lateral = Vector(
                (
                    1.0,
                    0.0,
                    0.0
                )
            )

            if not oriented:

                vertical = Vector(
                    (
                        0.0,
                        0.0,
                        1.0
                    )
                )

                return (
                    lateral,
                    vertical
                )

            if index == 0:

                tangent = (
                    centers[1]
                    - centers[0]
                )

            elif index == len(
                centers
            ) - 1:

                tangent = (
                    centers[-1]
                    - centers[-2]
                )

            else:

                tangent = (
                    centers[index + 1]
                    - centers[index - 1]
                )

            tangent.normalize()

            vertical = Vector(
                (
                    0.0,
                    -tangent.z,
                    tangent.y
                )
            )

            if vertical.length < 0.000001:

                vertical = Vector(
                    (
                        0.0,
                        0.0,
                        1.0
                    )
                )

            vertical.normalize()

            if vertical.z < 0.0:

                vertical *= -1.0

            return (
                lateral,
                vertical
            )

        for index, section in enumerate(
            sections
        ):

            center = centers[index]

            rx = section[2]
            rz = section[3]

            lateral, vertical = frame_at(
                index
            )

            for px, pz in loft_profile:

                point = (
                    center
                    + lateral
                    * (
                        px * rx
                    )
                    + vertical
                    * (
                        pz * rz
                    )
                )

                vertices.append(
                    tuple(point)
                )

        for section_index in range(
            len(sections) - 1
        ):

            a = (
                section_index
                * ring
            )

            b = (
                section_index + 1
            ) * ring

            for ring_index in range(
                ring
            ):

                nxt = (
                    ring_index + 1
                ) % ring

                faces.append(
                    (
                        a + ring_index,
                        b + ring_index,
                        b + nxt,
                        a + nxt
                    )
                )

        front_center = len(
            vertices
        )

        vertices.append(
            tuple(
                centers[0]
            )
        )

        for ring_index in range(
            ring
        ):

            nxt = (
                ring_index + 1
            ) % ring

            faces.append(
                (
                    front_center,
                    nxt,
                    ring_index
                )
            )

        rear_center = len(
            vertices
        )

        vertices.append(
            tuple(
                centers[-1]
            )
        )

        last_ring = (
            len(sections) - 1
        ) * ring

        for ring_index in range(
            ring
        ):

            nxt = (
                ring_index + 1
            ) % ring

            faces.append(
                (
                    rear_center,
                    last_ring + ring_index,
                    last_ring + nxt
                )
            )

        obj = create_mesh(
            name,
            vertices,
            faces,
            material
        )

        if subdivision > 0:

            subdivide(
                obj,
                subdivision
            )

        smooth(
            obj
        )

        bind(
            obj,
            group_name
        )

        return obj

