    # ========================================================
    # LIMB LOFT
    # ========================================================

    limb_profile = [

        (1.00, 0.00),
        (0.70, 0.70),
        (0.00, 1.00),
        (-0.70, 0.70),
        (-1.00, 0.00),
        (-0.70, -0.70),
        (0.00, -1.00),
        (0.70, -0.70),
    ]

    def build_limb(
        name,
        x,
        section_data,
        group_name,
        y_offset
    ):

        centers = [

            Vector(
                (
                    x,
                    section[0] + y_offset,
                    section[1]
                )
            )

            for section in section_data
        ]

        vertices = []
        faces = []

        ring = len(
            limb_profile
        )

        def frame_at(
            index
        ):

            if index == 0:

                tangent = (
                    centers[1]
                    - centers[0]
                )

            elif index == len(
                centers
            ) - 1:

                tangent = (
                    centers[-1]
                    - centers[-2]
                )

            else:

                tangent = (
                    centers[index + 1]
                    - centers[index - 1]
                )

            tangent.normalize()

            lateral = Vector(
                (
                    1.0,
                    0.0,
                    0.0
                )
            )

            depth = lateral.cross(
                tangent
            )

            if depth.length < 0.000001:

                depth = Vector(
                    (
                        0.0,
                        1.0,
                        0.0
                    )
                )

            depth.normalize()

            return lateral, depth

        for index, section in enumerate(
            section_data
        ):

            center = centers[index]

            width = section[2]
            depth_radius = section[3]

            lateral, depth = frame_at(index)

            for px, py in limb_profile:

                point = (
                    center
                    + lateral
                    * (
                        px * width
                    )
                    + depth
                    * (
                        py * depth_radius
                    )
                )

                vertices.append(
                    tuple(point)
                )

        for section_index in range(
            len(section_data) - 1
        ):

            a = (
                section_index
                * ring
            )

            b = (
                section_index + 1
            ) * ring

            for ring_index in range(
                ring
            ):

                nxt = (
                    ring_index + 1
                ) % ring

                faces.append(
                    (
                        a + ring_index,
                        b + ring_index,
                        b + nxt,
                        a + nxt
                    )
                )

        obj = create_mesh(
            name,
            vertices,
            faces,
            coat
        )

        obj.data.materials.append(
            dark
        )

        for polygon in obj.data.polygons:

            average_z = (
                sum(
                    obj.data.vertices[
                        vertex_index
                    ].co.z
                    for vertex_index
                    in polygon.vertices
                )
                / float(
                    len(
                        polygon.vertices
                    )
                )
            )

            if average_z < 0.610:

                polygon.material_index = 1

        subdivide(
            obj,
            1
        )

        smooth(
            obj
        )

        bind(
            obj,
            group_name
        )

        return obj

