    def build_hoof(
        name,
        x,
        heel_y,
        toe_y,
        group_name
    ):

        heel_width = 0.100
        toe_width = 0.148

        vertices = [

            (
                x - heel_width,
                heel_y,
                0.128
            ),

            (
                x + heel_width,
                heel_y,
                0.128
            ),

            (
                x - toe_width,
                toe_y,
                0.073
            ),

            (
                x + toe_width,
                toe_y,
                0.073
            ),

            (
                x - heel_width,
                heel_y,
                0.030
            ),

            (
                x + heel_width,
                heel_y,
                0.030
            ),

            (
                x - toe_width,
                toe_y,
                0.014
            ),

            (
                x + toe_width,
                toe_y,
                0.014
            ),
        ]

        faces = [

            (
                0,
                1,
                3,
                2
            ),

            (
                6,
                7,
                5,
                4
            ),

            (
                0,
                2,
                6,
                4
            ),

            (
                1,
                5,
                7,
                3
            ),

            (
                0,
                4,
                5,
                1
            ),

            (
                2,
                3,
                7,
                6
            ),
        ]

        hoof = create_mesh(
            name,
            vertices,
            faces,
            hoof_mat
        )

        bevel(
            hoof,
            0.018,
            3
        )

        smooth(
            hoof
        )

        bind(
            hoof,
            group_name
        )

        return hoof

