    def limb(
        name,
        x,
        sections,
        mat,
        group_name,
        y_offset=0.0
    ):

        centers = [

            Vector(
                (
                    x,
                    section[0] + y_offset,
                    section[1]
                )
            )

            for section in sections
        ]

        vertices = []
        faces = []

        ring_count = len(
            limb_profile
        )

        def frame(
            index
        ):

            if index == 0:

                tangent = (
                    centers[1]
                    - centers[0]
                )

            elif index == len(
                centers
            ) - 1:

                tangent = (
                    centers[-1]
                    - centers[-2]
                )

            else:

                tangent = (
                    centers[index + 1]
                    - centers[index - 1]
                )

            tangent.normalize()

            lateral = Vector(
                (
                    1.0,
                    0.0,
                    0.0
                )
            )

            depth = lateral.cross(
                tangent
            )

            if depth.length < 0.000001:

                depth = Vector(
                    (
                        0.0,
                        1.0,
                        0.0
                    )
                )

            depth.normalize()

            return (
                lateral,
                depth
            )

        for index, section in enumerate(
            sections
        ):

            center = centers[
                index
            ]

            width = section[2]
            depth_radius = section[3]

            lateral, depth = frame(
                index
            )

            for px, py in limb_profile:

                point = (
                    center
                    + lateral
                    * (
                        px * width
                    )
                    + depth
                    * (
                        py * depth_radius
                    )
                )

                vertices.append(
                    tuple(point)
                )

        for section_index in range(
            len(sections) - 1
        ):

            first = (
                section_index
                * ring_count
            )

            second = (
                section_index + 1
            ) * ring_count

            for ring_index in range(
                ring_count
            ):

                nxt = (
                    ring_index + 1
                ) % ring_count

                faces.append(
                    (
                        first + ring_index,
                        second + ring_index,
                        second + nxt,
                        first + nxt
                    )
                )

        obj = mesh_object(
            name,
            vertices,
            faces,
            mat,
            group_name
        )

        obj.data.materials.append(
            dark
        )

        for polygon in obj.data.polygons:

            average_z = (
                sum(
                    obj.data.vertices[
                        index
                    ].co.z
                    for index in polygon.vertices
                )
                / float(
                    len(
                        polygon.vertices
                    )
                )
            )

            if average_z < 0.60:

                polygon.material_index = 1

        subdivide(
            obj,
            1
        )

        smooth(
            obj
        )

        return obj

