def build_horse_model_v47_base(arm):

    import bpy
    import math

    from mathutils import Vector

    # ========================================================
    # BROKEN KNIGHT HORSE V47
    #
    # FULL FOUR-LEG STANCE REBUILD
    #
    # V46 rating:
    #
    # 48 / 100
    #
    # This pass deletes ALL existing limb geometry.
    #
    # ========================================================

    build_horse_model_v46_base(
        arm
    )

    print(
        "BROKEN_KNIGHT_HORSE_V47",
        "V46_BASE_COMPLETE"
    )

    # ========================================================
    # HELPERS
    # ========================================================

    def get_object(
        name
    ):

        return bpy.data.objects.get(
            name
        )

    def delete_prefix(
        prefix
    ):

        deleted = 0

        for obj in list(
            bpy.data.objects
        ):

            if obj.name.startswith(
                prefix
            ):

                bpy.data.objects.remove(
                    obj,
                    do_unlink=True
                )

                deleted += 1

        print(
            "V47_DELETE",
            prefix,
            deleted
        )

    def mesh_warp(
        name,
        function
    ):

        obj = get_object(
            name
        )

        if obj is None:

            print(
                "V47_MISSING_OBJECT",
                name
            )

            return

        if obj.type != "MESH":
            return

        for vertex in obj.data.vertices:

            vertex.co = Vector(
                function(
                    vertex.co.copy()
                )
            )

        obj.data.update()

    def transform_location(
        name,
        function
    ):

        obj = get_object(
            name
        )

        if obj is None:
            return

        obj.location = Vector(
            function(
                obj.location.copy()
            )
        )

    def local_scale(
        name,
        sx,
        sy,
        sz
    ):

        obj = get_object(
            name
        )

        if obj is None:
            return

        if obj.type != "MESH":
            return

        for vertex in obj.data.vertices:

            vertex.co.x *= sx
            vertex.co.y *= sy
            vertex.co.z *= sz

        obj.data.update()

    def smooth(
        obj
    ):

        if obj is None:
            return

        if obj.type != "MESH":
            return

        for polygon in obj.data.polygons:
            polygon.use_smooth = True

    def bind_new(
        obj,
        group_name
    ):

        obj.parent = arm

        group = obj.vertex_groups.new(
            name=group_name
        )

        group.add(
            list(
                range(
                    len(
                        obj.data.vertices
                    )
                )
            ),
            1.0,
            "REPLACE"
        )

        modifier = obj.modifiers.new(
            "HorseRig",
            "ARMATURE"
        )

        modifier.object = arm

    def create_mesh(
        name,
        vertices,
        faces,
        material,
        group_name
    ):

        mesh = bpy.data.meshes.new(
            name + "Mesh"
        )

        mesh.from_pydata(
            vertices,
            [],
            faces
        )

        mesh.update()

        obj = bpy.data.objects.new(
            name,
            mesh
        )

        bpy.context.collection.objects.link(
            obj
        )

        obj.data.materials.append(
            material
        )

        smooth(
            obj
        )

        bind_new(
            obj,
            group_name
        )

        return obj

    def subdivide(
        obj,
        levels=1
    ):

        bpy.ops.object.select_all(
            action="DESELECT"
        )

        obj.select_set(
            True
        )

        bpy.context.view_layer.objects.active = obj

        modifier = obj.modifiers.new(
            "V47 Subdivision",
            "SUBSURF"
        )

        modifier.subdivision_type = "CATMULL_CLARK"
        modifier.levels = levels
        modifier.render_levels = levels

        bpy.ops.object.modifier_apply(
            modifier=modifier.name
        )

    def bevel(
        obj,
        width,
        segments=3
    ):

        bpy.ops.object.select_all(
            action="DESELECT"
        )

        obj.select_set(
            True
        )

        bpy.context.view_layer.objects.active = obj

        modifier = obj.modifiers.new(
            "V47 Bevel",
            "BEVEL"
        )

        modifier.width = width
        modifier.segments = segments

        bpy.ops.object.modifier_apply(
            modifier=modifier.name
        )

    def curve_mesh(
        name,
        points,
        material,
        thickness,
        group_name,
        resolution=5
    ):

        data = bpy.data.curves.new(
            name=name + "Curve",
            type="CURVE"
        )

        data.dimensions = "3D"
        data.resolution_u = resolution
        data.bevel_depth = thickness
        data.bevel_resolution = 4

        spline = data.splines.new(
            "BEZIER"
        )

        spline.bezier_points.add(
            len(points) - 1
        )

        for index, point in enumerate(
            points
        ):

            bp = spline.bezier_points[
                index
            ]

            bp.co = point
            bp.handle_left_type = "AUTO"
            bp.handle_right_type = "AUTO"

        obj = bpy.data.objects.new(
            name,
            data
        )

        bpy.context.collection.objects.link(
            obj
        )

        obj.data.materials.append(
            material
        )

        bpy.ops.object.select_all(
            action="DESELECT"
        )

        obj.select_set(
            True
        )

        bpy.context.view_layer.objects.active = obj

        bpy.ops.object.convert(
            target="MESH"
        )

        obj = bpy.context.object
        obj.name = name

        smooth(
            obj
        )

        bind_new(
            obj,
            group_name
        )

        return obj

    def ellipsoid(
        name,
        location,
        scale,
        material,
        group_name
    ):

        bpy.ops.mesh.primitive_uv_sphere_add(
            segments=24,
            ring_count=16,
            location=location
        )

        obj = bpy.context.object

        obj.name = name
        obj.scale = Vector(
            scale
        )

        bpy.ops.object.transform_apply(
            location=False,
            rotation=False,
            scale=True
        )

        obj.data.materials.append(
            material
        )

        smooth(
            obj
        )

        bind_new(
            obj,
            group_name
        )

        return obj

    def side_prism(
        name,
        outline,
        x_min,
        x_max,
        material,
        group_name,
        bevel_width=0.0
    ):

        count = len(
            outline
        )

        vertices = []

        for y, z in outline:

            vertices.append(
                (
                    x_min,
                    y,
                    z
                )
            )

        for y, z in outline:

            vertices.append(
                (
                    x_max,
                    y,
                    z
                )
            )

        faces = [

            tuple(
                reversed(
                    range(count)
                )
            ),

            tuple(
                range(
                    count,
                    count * 2
                )
            ),
        ]

        for index in range(
            count
        ):

            nxt = (
                index + 1
            ) % count

            faces.append(
                (
                    index,
                    nxt,
                    count + nxt,
                    count + index
                )
            )

        obj = create_mesh(
            name,
            vertices,
            faces,
            material,
            group_name
        )

        if bevel_width > 0.0:

            bevel(
                obj,
                bevel_width,
                3
            )

        return obj

    coat = bpy.data.materials.get(
        "Riverwatch V46 Warm Bay"
    )

    dark = bpy.data.materials.get(
        "Riverwatch V46 Dark Points"
    )

    hoof_mat = bpy.data.materials.get(
        "Riverwatch V46 Hooves"
    )

    if coat is None:
        raise RuntimeError(
            "V47 could not find V46 coat material."
        )

    if dark is None:
        raise RuntimeError(
            "V47 could not find V46 dark material."
        )

    if hoof_mat is None:
        raise RuntimeError(
            "V47 could not find V46 hoof material."
        )

    # ========================================================
    # 1. BODY SILHOUETTE
    #
    # Current V46 side view still has:
    #
    # round rump
    # low abdomen
    # slightly heavy rear barrel
    #
    # ========================================================

    def torso_warp(
        co
    ):

        original_y = co.y
        original_z = co.z

        # Keep current overall length.

        # Narrow mid barrel.

        if (
            original_y > 0.10
            and original_y < 0.95
        ):

            co.x *= 0.965

        # Narrow rear quarter.

        elif original_y >= 0.95:

            co.x *= 0.940

        # Deep chest remains.

        # Raise belly sharply behind front ribs.

        if (
            original_y > 0.22
            and original_z < 1.08
        ):

            influence = min(
                1.0,
                max(
                    0.0,
                    (
                        1.08
                        - original_z
                    )
                    / 0.43
                )
            )

            if original_y < 0.75:

                co.z += (
                    0.075
                    * influence
                )

            elif original_y < 1.20:

                co.z += (
                    0.125
                    * influence
                )

            else:

                co.z += (
                    0.080
                    * influence
                )

        # Stretch only extreme rump backward.

        if original_y > 1.30:

            co.y = (
                1.30
                + (
                    original_y
                    - 1.30
                )
                * 1.06
            )

        # Flatten upper croup.

        if (
            original_y > 1.18
            and original_z > 1.46
        ):

            influence = min(
                1.0,
                max(
                    0.0,
                    (
                        original_y
                        - 1.18
                    )
                    / 0.50
                )
            )

            co.z -= (
                0.050
                * influence
            )

        # Raise lower rear outline.

        if (
            original_y > 1.18
            and original_z < 1.03
        ):

            influence = min(
                1.0,
                max(
                    0.0,
                    (
                        1.03
                        - original_z
                    )
                    / 0.32
                )
            )

            co.z += (
                0.055
                * influence
            )

        return co

    mesh_warp(
        "RiverwatchV46Torso",
        torso_warp
    )

    # ========================================================
    # 2. NECK
    #
    # Build stronger lower-neck connection.
    # ========================================================

    def neck_warp(
        co
    ):

        original_y = co.y
        original_z = co.z

        if original_y > -0.48:

            co.x *= 1.055

        # Raise throat line.

        if original_z < 1.64:

            influence = min(
                1.0,
                max(
                    0.0,
                    (
                        1.64
                        - original_z
                    )
                    / 0.30
                )
            )

            co.z += (
                0.045
                * influence
            )

            co.y += (
                0.040
                * influence
            )

        # Slight crest arch.

        if original_z > 1.84:

            influence = min(
                1.0,
                max(
                    0.0,
                    (
                        original_z
                        - 1.84
                    )
                    / 0.28
                )
            )

            co.y -= (
                0.025
                * influence
            )

        return co

    mesh_warp(
        "RiverwatchV46Neck",
        neck_warp
    )

    # ========================================================
    # 3. HEAD ANGLE
    #
    # Slight downward horse-like head carriage.
    # ========================================================

    head_pivot_y = -0.715
    head_pivot_z = 1.935
    head_angle = math.radians(
        4.5
    )

    head_cos = math.cos(
        head_angle
    )

    head_sin = math.sin(
        head_angle
    )

    def rotate_head_point(
        co
    ):

        dy = (
            co.y
            - head_pivot_y
        )

        dz = (
            co.z
            - head_pivot_z
        )

        new_y = (
            head_pivot_y
            + dy * head_cos
            - dz * head_sin
        )

        new_z = (
            head_pivot_z
            + dy * head_sin
            + dz * head_cos
        )

        co.y = new_y
        co.z = new_z

        return co

    mesh_warp(
        "RiverwatchV46Head",
        rotate_head_point
    )

    # Head slightly broader through cheek.

    def broaden_head(
        co
    ):

        if co.y > -1.05:

            co.x *= 1.040

        return co

    mesh_warp(
        "RiverwatchV46Head",
        broaden_head
    )

    # ========================================================
    # HEAD DETAILS FOLLOW ROTATION
    # ========================================================

    def rotate_location(
        location
    ):

        dy = (
            location.y
            - head_pivot_y
        )

        dz = (
            location.z
            - head_pivot_z
        )

        location.y = (
            head_pivot_y
            + dy * head_cos
            - dz * head_sin
        )

        location.z = (
            head_pivot_z
            + dy * head_sin
            + dz * head_cos
        )

        return location

