    # ========================================================
    # 5. GENERAL LEG BUILDER
    #
    # Each section:
    #
    # y
    # z
    # x center
    # x radius
    # depth radius
    #
    # This lets upper legs sit farther outside the torso
    # while lower limbs return naturally underneath.
    #
    # ========================================================

    limb_profile = [

        (
            1.000,
            0.000
        ),

        (
            0.707,
            0.707
        ),

        (
            0.000,
            1.000
        ),

        (
            -0.707,
            0.707
        ),

        (
            -1.000,
            0.000
        ),

        (
            -0.707,
            -0.707
        ),

        (
            0.000,
            -1.000
        ),

        (
            0.707,
            -0.707
        ),
    ]

    def build_leg(
        name,
        side,
        sections,
        group_name
    ):

        centers = [

            Vector(
                (
                    side * section[2],
                    section[0],
                    section[1]
                )
            )

            for section in sections
        ]

        vertices = []
        faces = []

        ring_count = len(
            limb_profile
        )

        def frame(
            index
        ):

            if index == 0:

                tangent = (
                    centers[1]
                    - centers[0]
                )

            elif index == len(
                centers
            ) - 1:

                tangent = (
                    centers[-1]
                    - centers[-2]
                )

            else:

                tangent = (
                    centers[
                        index + 1
                    ]
                    - centers[
                        index - 1
                    ]
                )

            if tangent.length < 0.000001:

                tangent = Vector(
                    (
                        0.0,
                        0.0,
                        -1.0
                    )
                )

            tangent.normalize()

            lateral = Vector(
                (
                    1.0,
                    0.0,
                    0.0
                )
            )

            depth_axis = lateral.cross(
                tangent
            )

            if depth_axis.length < 0.000001:

                depth_axis = Vector(
                    (
                        0.0,
                        1.0,
                        0.0
                    )
                )

            depth_axis.normalize()

            return (
                lateral,
                depth_axis
            )

        for index, section in enumerate(
            sections
        ):

            center = centers[
                index
            ]

            width = section[3]
            depth_radius = section[4]

            lateral, depth_axis = frame(
                index
            )

            for px, py in limb_profile:

                point = (
                    center
                    + lateral
                    * (
                        px
                        * width
                    )
                    + depth_axis
                    * (
                        py
                        * depth_radius
                    )
                )

                vertices.append(
                    tuple(point)
                )

        for section_index in range(
            len(sections) - 1
        ):

            first = (
                section_index
                * ring_count
            )

            second = (
                section_index + 1
            ) * ring_count

            for ring_index in range(
                ring_count
            ):

                nxt = (
                    ring_index + 1
                ) % ring_count

                faces.append(
                    (
                        first + ring_index,
                        second + ring_index,
                        second + nxt,
                        first + nxt
                    )
                )

        obj = create_mesh(
            name,
            vertices,
            faces,
            coat,
            group_name
        )

        obj.data.materials.append(
            dark
        )

        # Dark lower legs.

        for polygon in obj.data.polygons:

            average_z = (
                sum(
                    obj.data.vertices[
                        vertex_index
                    ].co.z
                    for vertex_index in polygon.vertices
                )
                / float(
                    len(
                        polygon.vertices
                    )
                )
            )

            if average_z < 0.58:

                polygon.material_index = 1

        subdivide(
            obj,
            1
        )

        smooth(
            obj
        )

        return obj

