    # ========================================================
    # BODY BUILDER
    #
    # Ten-point cross section.
    #
    # CRITICAL DIFFERENCE FROM V48:
    #
    # Broad pair of dorsal vertices.
    # Broad pair of belly vertices.
    #
    # No central spine pole.
    # No central belly pole.
    #
    # ========================================================

    def build_body(
        name,
        stations
    ):

        vertices = []
        faces = []

        ring_size = 10

        for station in stations:

            y = station[0]

            top_z = station[1]
            mid_z = station[2]
            belly_z = station[3]

            width = station[4]

            upper_z = (
                mid_z
                + (
                    top_z
                    - mid_z
                )
                * 0.55
            )

            lower_z = (
                belly_z
                + (
                    mid_z
                    - belly_z
                )
                * 0.42
            )

            ring = [

                # Broad top-left.

                (
                    -width * 0.28,
                    y,
                    top_z
                ),

                # Broad top-right.

                (
                    width * 0.28,
                    y,
                    top_z
                ),

                # Upper-right shoulder/barrel.

                (
                    width * 0.78,
                    y,
                    upper_z
                ),

                # Widest right.

                (
                    width,
                    y,
                    mid_z
                ),

                # Lower-right.

                (
                    width * 0.82,
                    y,
                    lower_z
                ),

                # Broad belly-right.

                (
                    width * 0.38,
                    y,
                    belly_z
                ),

                # Broad belly-left.

                (
                    -width * 0.38,
                    y,
                    belly_z
                ),

                # Lower-left.

                (
                    -width * 0.82,
                    y,
                    lower_z
                ),

                # Widest left.

                (
                    -width,
                    y,
                    mid_z
                ),

                # Upper-left.

                (
                    -width * 0.78,
                    y,
                    upper_z
                ),
            ]

            vertices.extend(
                ring
            )

        for station_index in range(
            len(stations) - 1
        ):

            first = (
                station_index
                * ring_size
            )

            second = (
                station_index + 1
            ) * ring_size

            for ring_index in range(
                ring_size
            ):

                nxt = (
                    ring_index + 1
                ) % ring_size

                faces.append(
                    (
                        first + ring_index,
                        second + ring_index,
                        second + nxt,
                        first + nxt
                    )
                )

        # Front cap.

        faces.append(
            tuple(
                reversed(
                    range(
                        ring_size
                    )
                )
            )
        )

        # Rear cap.

        last_start = (
            len(stations) - 1
        ) * ring_size

        faces.append(
            tuple(
                range(
                    last_start,
                    last_start + ring_size
                )
            )
        )

        obj = create_mesh(
            name,
            vertices,
            faces,
            coat,
            "body"
        )

        # ONLY ONE LEVEL.
        #
        # This deliberately avoids the V48 surface collapse.

        subdivide(
            obj,
            1
        )

        smooth(
            obj
        )

        return obj

