def build_horse_model_v50_base(arm):

    import bpy
    import math

    from mathutils import Vector

    # ========================================================
    # BROKEN KNIGHT HORSE V50
    #
    # REFERENCE ANATOMY REBUILD
    #
    # V49 = 51 / 100
    #
    # Keep:
    #
    # V49 clean torso
    # tack / blanket / bags / bridle
    #
    # Replace:
    #
    # neck
    # head
    # face
    # all four legs
    # all four hooves
    # mane
    # tail
    #
    # ========================================================

    build_horse_model_v49_base(
        arm
    )

    print(
        "BROKEN_KNIGHT_HORSE_V50",
        "V49_BASE_COMPLETE"
    )

    # ========================================================
    # HELPERS
    # ========================================================

    def get_object(
        name
    ):

        return bpy.data.objects.get(
            name
        )

    def delete_prefix(
        prefix
    ):

        deleted = 0

        for obj in list(
            bpy.data.objects
        ):

            if obj.name.startswith(
                prefix
            ):

                bpy.data.objects.remove(
                    obj,
                    do_unlink=True
                )

                deleted += 1

        print(
            "V50_DELETE",
            prefix,
            deleted
        )

    def smooth(
        obj
    ):

        if obj is None:
            return

        if obj.type != "MESH":
            return

        for polygon in obj.data.polygons:
            polygon.use_smooth = True

    def bind_new(
        obj,
        group_name
    ):

        obj.parent = arm

        group = obj.vertex_groups.new(
            name=group_name
        )

        group.add(
            list(
                range(
                    len(
                        obj.data.vertices
                    )
                )
            ),
            1.0,
            "REPLACE"
        )

        modifier = obj.modifiers.new(
            "HorseRig",
            "ARMATURE"
        )

        modifier.object = arm

    def create_mesh(
        name,
        vertices,
        faces,
        material,
        group_name
    ):

        mesh = bpy.data.meshes.new(
            name + "Mesh"
        )

        mesh.from_pydata(
            vertices,
            [],
            faces
        )

        mesh.update()

        obj = bpy.data.objects.new(
            name,
            mesh
        )

        bpy.context.collection.objects.link(
            obj
        )

        obj.data.materials.append(
            material
        )

        smooth(
            obj
        )

        bind_new(
            obj,
            group_name
        )

        return obj

    def subdivide(
        obj,
        levels=1
    ):

        bpy.ops.object.select_all(
            action="DESELECT"
        )

        obj.select_set(
            True
        )

        bpy.context.view_layer.objects.active = obj

        modifier = obj.modifiers.new(
            "V50 Subdivision",
            "SUBSURF"
        )

        modifier.subdivision_type = "CATMULL_CLARK"
        modifier.levels = levels
        modifier.render_levels = levels

        bpy.ops.object.modifier_apply(
            modifier=modifier.name
        )

    def bevel(
        obj,
        width,
        segments=3
    ):

        bpy.ops.object.select_all(
            action="DESELECT"
        )

        obj.select_set(
            True
        )

        bpy.context.view_layer.objects.active = obj

        modifier = obj.modifiers.new(
            "V50 Bevel",
            "BEVEL"
        )

        modifier.width = width
        modifier.segments = segments

        bpy.ops.object.modifier_apply(
            modifier=modifier.name
        )

    def mesh_warp(
        name,
        function
    ):

        obj = get_object(
            name
        )

        if obj is None:

            print(
                "V50_MISSING_OBJECT",
                name
            )

            return

        if obj.type != "MESH":
            return

        for vertex in obj.data.vertices:

            vertex.co = Vector(
                function(
                    vertex.co.copy()
                )
            )

        obj.data.update()

    def ellipsoid(
        name,
        location,
        scale,
        material,
        group_name
    ):

        bpy.ops.mesh.primitive_uv_sphere_add(
            segments=28,
            ring_count=18,
            location=location
        )

        obj = bpy.context.object

        obj.name = name
        obj.scale = Vector(
            scale
        )

        bpy.ops.object.transform_apply(
            location=False,
            rotation=False,
            scale=True
        )

        obj.data.materials.append(
            material
        )

        smooth(
            obj
        )

        bind_new(
            obj,
            group_name
        )

        return obj

    def side_prism(
        name,
        outline,
        x_min,
        x_max,
        material,
        group_name,
        bevel_width=0.0
    ):

        count = len(
            outline
        )

        vertices = []

        for y, z in outline:

            vertices.append(
                (
                    x_min,
                    y,
                    z
                )
            )

        for y, z in outline:

            vertices.append(
                (
                    x_max,
                    y,
                    z
                )
            )

        faces = [

            tuple(
                reversed(
                    range(count)
                )
            ),

            tuple(
                range(
                    count,
                    count * 2
                )
            ),
        ]

        for index in range(
            count
        ):

            nxt = (
                index + 1
            ) % count

            faces.append(
                (
                    index,
                    nxt,
                    count + nxt,
                    count + index
                )
            )

        obj = create_mesh(
            name,
            vertices,
            faces,
            material,
            group_name
        )

        if bevel_width > 0.0:

            bevel(
                obj,
                bevel_width,
                2
            )

        return obj

    # ========================================================
    # MATERIALS
    # ========================================================

    coat = bpy.data.materials.get(
        "Riverwatch V49 Warm Bay"
    )

    dark = bpy.data.materials.get(
        "Riverwatch V49 Dark Points"
    )

    muzzle_mat = bpy.data.materials.get(
        "Riverwatch V49 Muzzle"
    )

    eye_mat = bpy.data.materials.get(
        "Riverwatch V49 Eyes"
    )

    hoof_mat = bpy.data.materials.get(
        "Riverwatch V49 Hooves"
    )

    if coat is None:
        raise RuntimeError(
            "V50 could not find V49 coat material."
        )

    if dark is None:
        raise RuntimeError(
            "V50 could not find V49 dark material."
        )

    if muzzle_mat is None:
        raise RuntimeError(
            "V50 could not find V49 muzzle material."
        )

    if eye_mat is None:
        raise RuntimeError(
            "V50 could not find V49 eye material."
        )

    if hoof_mat is None:
        raise RuntimeError(
            "V50 could not find V49 hoof material."
        )

    # ========================================================
    # RICHER BAY COLOR
    # ========================================================

    coat.diffuse_color = (
        0.185,
        0.050,
        0.017,
        1.0
    )

    if coat.use_nodes:

        node = coat.node_tree.nodes.get(
            "Principled BSDF"
        )

        if node is not None:

            if "Base Color" in node.inputs:

                node.inputs[
                    "Base Color"
                ].default_value = (
                    0.185,
                    0.050,
                    0.017,
                    1.0
                )

            if "Roughness" in node.inputs:

                node.inputs[
                    "Roughness"
                ].default_value = 0.60

    # ========================================================
    # GENTLE V49 TORSO REFINEMENT
    #
    # KEEP the clean body.
    #
    # Only:
    #
    # slightly stronger withers
    # slightly longer croup slope
    # slightly tighter abdomen
    #
    # ========================================================

    def torso_refine(
        co
    ):

        y = co.y
        z = co.z

        # ----------------------------------------------------
        # WITHERS
        # ----------------------------------------------------

        if (
            y > -0.31
            and y < 0.04
            and z > 1.45
        ):

            center = -0.14
            radius = 0.18

            influence = (
                1.0
                - abs(
                    y - center
                ) / radius
            )

            influence = max(
                0.0,
                influence
            )

            co.z += (
                0.045
                * influence
            )

            co.x *= (
                1.0
                - 0.020
                * influence
            )

        # ----------------------------------------------------
        # ABDOMEN
        # ----------------------------------------------------

        if (
            y > 0.65
            and y < 1.12
            and z < 0.98
        ):

            influence = (
                1.0
                - abs(
                    y - 0.88
                ) / 0.25
            )

            influence = max(
                0.0,
                influence
            )

            co.z += (
                0.030
                * influence
            )

        # ----------------------------------------------------
        # CROUP SLOPE
        # ----------------------------------------------------

        if (
            y > 1.34
            and z > 1.42
        ):

            influence = min(
                1.0,
                max(
                    0.0,
                    (
                        y - 1.34
                    ) / 0.32
                )
            )

            co.z -= (
                0.040
                * influence
            )

            co.y += (
                0.025
                * influence
            )

        return co

