    def build_tail_ribbon(
        name,
        x_center,
        stations,
        material,
        group_name
    ):

        # station:
        #
        # y
        # z
        # half width x
        # half depth y

        vertices = []
        faces = []

        for station in stations:

            y = station[0]
            z = station[1]
            half_width = station[2]
            half_depth = station[3]

            vertices.extend(
                [

                    (
                        x_center - half_width,
                        y - half_depth,
                        z
                    ),

                    (
                        x_center + half_width,
                        y - half_depth,
                        z
                    ),

                    (
                        x_center + half_width,
                        y + half_depth,
                        z
                    ),

                    (
                        x_center - half_width,
                        y + half_depth,
                        z
                    ),
                ]
            )

        for station_index in range(
            len(stations) - 1
        ):

            first = (
                station_index
                * 4
            )

            second = (
                station_index + 1
            ) * 4

            faces.extend(
                [

                    (
                        first + 0,
                        first + 1,
                        second + 1,
                        second + 0
                    ),

                    (
                        first + 1,
                        first + 2,
                        second + 2,
                        second + 1
                    ),

                    (
                        first + 2,
                        first + 3,
                        second + 3,
                        second + 2
                    ),

                    (
                        first + 3,
                        first + 0,
                        second + 0,
                        second + 3
                    ),
                ]
            )

        faces.append(
            (
                0,
                3,
                2,
                1
            )
        )

        last = (
            len(stations) - 1
        ) * 4

        faces.append(
            (
                last + 0,
                last + 1,
                last + 2,
                last + 3
            )
        )

        obj = create_mesh(
            name,
            vertices,
            faces,
            material,
            group_name
        )

        subdivide(
            obj,
            1
        )

        smooth(
            obj
        )

        return obj

