def build_horse_model_v51_base(arm):

    import bpy
    import math

    from mathutils import Vector

    # ========================================================
    # BROKEN KNIGHT HORSE V51
    #
    # REFERENCE SHAPE LOCK
    #
    # New modeling approach:
    #
    # SIDE-SILHOUETTE-CONTROLLED SHELLS
    #
    # Neck/head and limbs are no longer built primarily
    # from circular cross-section chains.
    #
    # ========================================================

    build_horse_model_v50_base(
        arm
    )

    print(
        "BROKEN_KNIGHT_HORSE_V51",
        "V50_BASE_COMPLETE"
    )

    # ========================================================
    # HELPERS
    # ========================================================

    def get_object(
        name
    ):

        return bpy.data.objects.get(
            name
        )

    def delete_prefix(
        prefix
    ):

        deleted = 0

        for obj in list(
            bpy.data.objects
        ):

            if obj.name.startswith(
                prefix
            ):

                bpy.data.objects.remove(
                    obj,
                    do_unlink=True
                )

                deleted += 1

        print(
            "V51_DELETE",
            prefix,
            deleted
        )

    def smooth(
        obj
    ):

        if obj is None:
            return

        if obj.type != "MESH":
            return

        for polygon in obj.data.polygons:
            polygon.use_smooth = True

    def bind_new(
        obj,
        group_name
    ):

        obj.parent = arm

        group = obj.vertex_groups.new(
            name=group_name
        )

        group.add(
            list(
                range(
                    len(
                        obj.data.vertices
                    )
                )
            ),
            1.0,
            "REPLACE"
        )

        modifier = obj.modifiers.new(
            "HorseRig",
            "ARMATURE"
        )

        modifier.object = arm

    def create_mesh(
        name,
        vertices,
        faces,
        material,
        group_name
    ):

        mesh = bpy.data.meshes.new(
            name + "Mesh"
        )

        mesh.from_pydata(
            vertices,
            [],
            faces
        )

        mesh.update()

        obj = bpy.data.objects.new(
            name,
            mesh
        )

        bpy.context.collection.objects.link(
            obj
        )

        obj.data.materials.append(
            material
        )

        smooth(
            obj
        )

        bind_new(
            obj,
            group_name
        )

        return obj

    def bevel(
        obj,
        width,
        segments=3
    ):

        bpy.ops.object.select_all(
            action="DESELECT"
        )

        obj.select_set(
            True
        )

        bpy.context.view_layer.objects.active = obj

        modifier = obj.modifiers.new(
            "V51 Bevel",
            "BEVEL"
        )

        modifier.width = width
        modifier.segments = segments

        bpy.ops.object.modifier_apply(
            modifier=modifier.name
        )

    def mesh_warp(
        name,
        function
    ):

        obj = get_object(
            name
        )

        if obj is None:

            print(
                "V51_MISSING_OBJECT",
                name
            )

            return

        if obj.type != "MESH":
            return

        for vertex in obj.data.vertices:

            vertex.co = Vector(
                function(
                    vertex.co.copy()
                )
            )

        obj.data.update()

    def ellipsoid(
        name,
        location,
        scale,
        material,
        group_name
    ):

        bpy.ops.mesh.primitive_uv_sphere_add(
            segments=28,
            ring_count=18,
            location=location
        )

        obj = bpy.context.object

        obj.name = name
        obj.scale = Vector(
            scale
        )

        bpy.ops.object.transform_apply(
            location=False,
            rotation=False,
            scale=True
        )

        obj.data.materials.append(
            material
        )

        smooth(
            obj
        )

        bind_new(
            obj,
            group_name
        )

        return obj

    # ========================================================
    # SIDE SHELL
    #
    # outline item:
    #
    # (
    #   y,
    #   z,
    #   half-width-x
    # )
    #
    # Gives exact side silhouette while preserving
    # dimensional width.
    #
    # ========================================================

    def build_side_shell(
        name,
        outline,
        center_x,
        material,
        group_name,
        bevel_width=0.0
    ):

        count = len(
            outline
        )

        vertices = []

        # Left surface.

        for y, z, half_width in outline:

            vertices.append(
                (
                    center_x - half_width,
                    y,
                    z
                )
            )

        # Right surface.

        for y, z, half_width in outline:

            vertices.append(
                (
                    center_x + half_width,
                    y,
                    z
                )
            )

        faces = [

            tuple(
                reversed(
                    range(
                        count
                    )
                )
            ),

            tuple(
                range(
                    count,
                    count * 2
                )
            ),
        ]

        for index in range(
            count
        ):

            nxt = (
                index + 1
            ) % count

            faces.append(
                (
                    index,
                    nxt,
                    count + nxt,
                    count + index
                )
            )

        obj = create_mesh(
            name,
            vertices,
            faces,
            material,
            group_name
        )

        if bevel_width > 0.0:

            bevel(
                obj,
                bevel_width,
                3
            )

        smooth(
            obj
        )

        return obj

    # ========================================================
    # MATERIALS
    # ========================================================

    coat = bpy.data.materials.get(
        "Riverwatch V50 Warm Bay"
    )

    dark = bpy.data.materials.get(
        "Riverwatch V50 Dark Points"
    )

    muzzle_mat = bpy.data.materials.get(
        "Riverwatch V50 Muzzle"
    )

    eye_mat = bpy.data.materials.get(
        "Riverwatch V50 Eyes"
    )

    hoof_mat = bpy.data.materials.get(
        "Riverwatch V50 Hooves"
    )

    if coat is None:
        raise RuntimeError(
            "V51 missing V50 Warm Bay material."
        )

    if dark is None:
        raise RuntimeError(
            "V51 missing V50 Dark Points material."
        )

    if muzzle_mat is None:
        raise RuntimeError(
            "V51 missing V50 Muzzle material."
        )

    if eye_mat is None:
        raise RuntimeError(
            "V51 missing V50 Eyes material."
        )

    if hoof_mat is None:
        raise RuntimeError(
            "V51 missing V50 Hooves material."
        )

    # ========================================================
    # 1. V50 TORSO
    #
    # KEEP CLEAN SURFACE.
    #
    # REFERENCE PROPORTION CORRECTION:
    #
    # longer rear half
    # shorter front projection
    # stronger shoulder
    # raised belly
    # wider / stretched croup
    #
    # ========================================================

    def torso_reference_warp(
        co
    ):

        y = co.y
        z = co.z

        original_y = y

        # ----------------------------------------------------
        # SHORTEN FRONT PROJECTION
        # ----------------------------------------------------

        if y < -0.08:

            pivot = -0.08

            co.y = (
                pivot
                + (
                    y - pivot
                )
                * 0.93
            )

        # ----------------------------------------------------
        # LENGTHEN REAR BODY
        # ----------------------------------------------------

        elif y > 0.72:

            pivot = 0.72

            co.y = (
                pivot
                + (
                    y - pivot
                )
                * 1.085
            )

        # ----------------------------------------------------
        # DEEPER / WIDER SHOULDER
        # ----------------------------------------------------

        if (
            original_y > -0.35
            and original_y < 0.14
        ):

            co.x *= 1.045

            if z < 1.03:

                co.z -= 0.025

        # ----------------------------------------------------
        # FULLER RIB CAGE
        # ----------------------------------------------------

        if (
            original_y > 0.10
            and original_y < 0.72
        ):

            co.x *= 1.025

        # ----------------------------------------------------
        # RAISED ABDOMEN BEHIND CHEST
        # ----------------------------------------------------

        if (
            original_y > 0.55
            and original_y < 1.18
            and z < 0.97
        ):

            center = 0.88
            radius = 0.36

            influence = (
                1.0
                - abs(
                    original_y - center
                ) / radius
            )

            influence = max(
                0.0,
                influence
            )

            co.z += (
                0.060
                * influence
            )

        # ----------------------------------------------------
        # STRONGER LOIN
        # ----------------------------------------------------

        if (
            original_y > 0.95
            and original_y < 1.30
            and z > 1.40
        ):

            co.z += 0.018

            co.x *= 1.020

        # ----------------------------------------------------
        # WIDER CROUP
        # ----------------------------------------------------

        if original_y > 1.20:

            co.x *= 1.045

        # ----------------------------------------------------
        # STRETCHED CROUP
        #
        # Avoid a round ball.
        # ----------------------------------------------------

        if original_y > 1.30:

            influence = min(
                1.0,
                max(
                    0.0,
                    (
                        original_y - 1.30
                    )
                    / 0.38
                )
            )

            co.y += (
                0.045
                * influence
            )

            if z > 1.46:

                co.z -= (
                    0.030
                    * influence
                )

        return co

