    # ========================================================
    # VOLUMETRIC LIMB BUILDER
    #
    # Unlike V51 flat shells:
    #
    # sections follow actual joint chain
    # cross sections rotate perpendicular to limb
    # joint widths are independently controlled
    #
    # ========================================================

    limb_profile = [

        (
            1.000,
            0.000
        ),

        (
            0.809,
            0.588
        ),

        (
            0.309,
            0.951
        ),

        (
            -0.309,
            0.951
        ),

        (
            -0.809,
            0.588
        ),

        (
            -1.000,
            0.000
        ),

        (
            -0.809,
            -0.588
        ),

        (
            -0.309,
            -0.951
        ),

        (
            0.309,
            -0.951
        ),

        (
            0.809,
            -0.588
        ),
    ]

    def build_limb(
        name,
        side,
        sections,
        group_name
    ):

        # section:
        #
        # y
        # z
        # absolute x center
        # lateral radius
        # depth radius

        centers = []

        for section in sections:

            centers.append(
                Vector(
                    (
                        side * section[2],
                        section[0],
                        section[1]
                    )
                )
            )

        vertices = []
        faces = []

        ring_size = len(
            limb_profile
        )

        def get_frame(
            index
        ):

            if index == 0:

                tangent = (
                    centers[1]
                    - centers[0]
                )

            elif index == len(
                centers
            ) - 1:

                tangent = (
                    centers[-1]
                    - centers[-2]
                )

            else:

                tangent = (
                    centers[index + 1]
                    - centers[index - 1]
                )

            if tangent.length < 0.000001:

                tangent = Vector(
                    (
                        0.0,
                        0.0,
                        -1.0
                    )
                )

            tangent.normalize()

            lateral = Vector(
                (
                    1.0,
                    0.0,
                    0.0
                )
            )

            depth_axis = lateral.cross(
                tangent
            )

            if depth_axis.length < 0.000001:

                depth_axis = Vector(
                    (
                        0.0,
                        1.0,
                        0.0
                    )
                )

            depth_axis.normalize()

            return (
                lateral,
                depth_axis
            )

        for index, section in enumerate(
            sections
        ):

            center = centers[
                index
            ]

            lateral_radius = section[3]
            depth_radius = section[4]

            lateral, depth_axis = get_frame(
                index
            )

            for px, py in limb_profile:

                point = (
                    center
                    + lateral
                    * (
                        px
                        * lateral_radius
                    )
                    + depth_axis
                    * (
                        py
                        * depth_radius
                    )
                )

                vertices.append(
                    tuple(point)
                )

        for section_index in range(
            len(sections) - 1
        ):

            first = (
                section_index
                * ring_size
            )

            second = (
                section_index + 1
            ) * ring_size

            for ring_index in range(
                ring_size
            ):

                nxt = (
                    ring_index + 1
                ) % ring_size

                faces.append(
                    (
                        first + ring_index,
                        second + ring_index,
                        second + nxt,
                        first + nxt
                    )
                )

        faces.append(
            tuple(
                reversed(
                    range(
                        ring_size
                    )
                )
            )
        )

        last = (
            len(sections) - 1
        ) * ring_size

        faces.append(
            tuple(
                range(
                    last,
                    last + ring_size
                )
            )
        )

        obj = create_mesh(
            name,
            vertices,
            faces,
            coat,
            group_name
        )

        obj.data.materials.append(
            dark
        )

        for polygon in obj.data.polygons:

            average_z = (
                sum(
                    obj.data.vertices[
                        vertex_index
                    ].co.z
                    for vertex_index in polygon.vertices
                )
                / float(
                    len(
                        polygon.vertices
                    )
                )
            )

            if average_z < 0.52:

                polygon.material_index = 1

        subdivide(
            obj,
            1
        )

        smooth(
            obj
        )

        return obj

