def build_horse_model_v54_base(arm):

    import bpy
    import math

    from mathutils import Vector

    # ========================================================
    # BROKEN KNIGHT HORSE V54
    #
    # TOTAL ANATOMY RESET
    #
    # V53 = 48 / 100
    #
    # We keep the readable tack.
    #
    # Horse anatomy is rebuilt from scratch underneath it.
    #
    # ========================================================

    build_horse_model_v53_base(
        arm
    )

    print(
        "BROKEN_KNIGHT_HORSE_V54",
        "V53_BASE_COMPLETE"
    )

    # ========================================================
    # HELPERS
    # ========================================================

    def get_object(
        name
    ):

        return bpy.data.objects.get(
            name
        )

    def delete_prefix(
        prefix
    ):

        deleted = 0

        for obj in list(
            bpy.data.objects
        ):

            if obj.name.startswith(
                prefix
            ):

                bpy.data.objects.remove(
                    obj,
                    do_unlink=True
                )

                deleted += 1

        print(
            "V54_DELETE",
            prefix,
            deleted
        )

    def smooth(
        obj
    ):

        if obj is None:
            return

        if obj.type != "MESH":
            return

        for polygon in obj.data.polygons:
            polygon.use_smooth = True

    def bind_new(
        obj,
        group_name
    ):

        obj.parent = arm

        group = obj.vertex_groups.new(
            name=group_name
        )

        group.add(
            list(
                range(
                    len(
                        obj.data.vertices
                    )
                )
            ),
            1.0,
            "REPLACE"
        )

        modifier = obj.modifiers.new(
            "HorseRig",
            "ARMATURE"
        )

        modifier.object = arm

    def create_mesh(
        name,
        vertices,
        faces,
        material,
        group_name
    ):

        mesh = bpy.data.meshes.new(
            name + "Mesh"
        )

        mesh.from_pydata(
            vertices,
            [],
            faces
        )

        mesh.update()

        obj = bpy.data.objects.new(
            name,
            mesh
        )

        bpy.context.collection.objects.link(
            obj
        )

        obj.data.materials.append(
            material
        )

        smooth(
            obj
        )

        bind_new(
            obj,
            group_name
        )

        return obj

    def subdivide(
        obj,
        levels=1
    ):

        bpy.ops.object.select_all(
            action="DESELECT"
        )

        obj.select_set(
            True
        )

        bpy.context.view_layer.objects.active = obj

        modifier = obj.modifiers.new(
            "V54 Subdivision",
            "SUBSURF"
        )

        modifier.subdivision_type = "CATMULL_CLARK"
        modifier.levels = levels
        modifier.render_levels = levels

        bpy.ops.object.modifier_apply(
            modifier=modifier.name
        )

    def bevel(
        obj,
        width,
        segments=3
    ):

        bpy.ops.object.select_all(
            action="DESELECT"
        )

        obj.select_set(
            True
        )

        bpy.context.view_layer.objects.active = obj

        modifier = obj.modifiers.new(
            "V54 Bevel",
            "BEVEL"
        )

        modifier.width = width
        modifier.segments = segments

        bpy.ops.object.modifier_apply(
            modifier=modifier.name
        )

    def ellipsoid(
        name,
        location,
        scale,
        material,
        group_name,
        rotation_x=0.0
    ):

        bpy.ops.mesh.primitive_uv_sphere_add(
            segments=28,
            ring_count=18,
            location=location
        )

        obj = bpy.context.object

        obj.name = name

        obj.scale = Vector(
            scale
        )

        obj.rotation_euler.x = math.radians(
            rotation_x
        )

        bpy.ops.object.transform_apply(
            location=False,
            rotation=True,
            scale=True
        )

        obj.data.materials.append(
            material
        )

        smooth(
            obj
        )

        bind_new(
            obj,
            group_name
        )

        return obj

    def build_ring_cage(
        name,
        stations,
        material,
        group_name,
        subdivision=1
    ):

        # station:
        #
        # y
        # top_z
        # upper_z
        # center_z
        # lower_z
        # belly_z
        # top_width
        # upper_width
        # middle_width
        # lower_width
        # belly_width

        vertices = []
        faces = []

        ring_size = 10

        for s in stations:

            y = s[0]

            top_z = s[1]
            upper_z = s[2]
            center_z = s[3]
            lower_z = s[4]
            belly_z = s[5]

            top_w = s[6]
            upper_w = s[7]
            middle_w = s[8]
            lower_w = s[9]
            belly_w = s[10]

            ring = [

                (
                    -top_w,
                    y,
                    top_z
                ),

                (
                    top_w,
                    y,
                    top_z
                ),

                (
                    upper_w,
                    y,
                    upper_z
                ),

                (
                    middle_w,
                    y,
                    center_z
                ),

                (
                    lower_w,
                    y,
                    lower_z
                ),

                (
                    belly_w,
                    y,
                    belly_z
                ),

                (
                    -belly_w,
                    y,
                    belly_z
                ),

                (
                    -lower_w,
                    y,
                    lower_z
                ),

                (
                    -middle_w,
                    y,
                    center_z
                ),

                (
                    -upper_w,
                    y,
                    upper_z
                ),
            ]

            vertices.extend(
                ring
            )

        for station_index in range(
            len(stations) - 1
        ):

            first = (
                station_index
                * ring_size
            )

            second = (
                station_index + 1
            ) * ring_size

            for ring_index in range(
                ring_size
            ):

                nxt = (
                    ring_index + 1
                ) % ring_size

                faces.append(
                    (
                        first + ring_index,
                        second + ring_index,
                        second + nxt,
                        first + nxt
                    )
                )

        faces.append(
            tuple(
                reversed(
                    range(
                        ring_size
                    )
                )
            )
        )

        last = (
            len(stations) - 1
        ) * ring_size

        faces.append(
            tuple(
                range(
                    last,
                    last + ring_size
                )
            )
        )

        obj = create_mesh(
            name,
            vertices,
            faces,
            material,
            group_name
        )

        if subdivision > 0:

            subdivide(
                obj,
                subdivision
            )

        smooth(
            obj
        )

        return obj

    def tapered_segment(
        name,
        point_a,
        point_b,
        radius_a,
        radius_b,
        material,
        group_name,
        vertices=12
    ):

        a = Vector(
            point_a
        )

        b = Vector(
            point_b
        )

        direction = (
            b - a
        )

        length = direction.length

        if length < 0.00001:
            raise RuntimeError(
                "V54 zero-length segment: " + name
            )

        midpoint = (
            a + b
        ) * 0.5

        bpy.ops.mesh.primitive_cone_add(
            vertices=vertices,
            radius1=radius_a,
            radius2=radius_b,
            depth=length,
            location=midpoint
        )

        obj = bpy.context.object

        obj.name = name

        direction.normalize()

        obj.rotation_mode = "QUATERNION"

        obj.rotation_quaternion = direction.to_track_quat(
            "Z",
            "Y"
        )

        bpy.ops.object.transform_apply(
            location=False,
            rotation=True,
            scale=False
        )

        obj.data.materials.append(
            material
        )

        smooth(
            obj
        )

        bind_new(
            obj,
            group_name
        )

        return obj

    def hoof_box(
        name,
        location,
        size,
        rotation_x,
        material,
        group_name
    ):

        bpy.ops.mesh.primitive_cube_add(
            location=location
        )

        obj = bpy.context.object

        obj.name = name

        obj.scale = Vector(
            (
                size[0] * 0.5,
                size[1] * 0.5,
                size[2] * 0.5
            )
        )

        obj.rotation_euler.x = math.radians(
            rotation_x
        )

        bpy.ops.object.transform_apply(
            location=False,
            rotation=True,
            scale=True
        )

        obj.data.materials.append(
            material
        )

        bevel(
            obj,
            0.025,
            3
        )

        bind_new(
            obj,
            group_name
        )

        return obj

    def side_shell(
        name,
        outline,
        center_x,
        material,
        group_name,
        bevel_width=0.0
    ):

        count = len(
            outline
        )

        vertices = []

        for y, z, half_width in outline:

            vertices.append(
                (
                    center_x - half_width,
                    y,
                    z
                )
            )

        for y, z, half_width in outline:

            vertices.append(
                (
                    center_x + half_width,
                    y,
                    z
                )
            )

        faces = [

            tuple(
                reversed(
                    range(
                        count
                    )
                )
            ),

            tuple(
                range(
                    count,
                    count * 2
                )
            ),
        ]

        for index in range(
            count
        ):

            nxt = (
                index + 1
            ) % count

            faces.append(
                (
                    index,
                    nxt,
                    count + nxt,
                    count + index
                )
            )

        obj = create_mesh(
            name,
            vertices,
            faces,
            material,
            group_name
        )

        if bevel_width > 0.0:

            bevel(
                obj,
                bevel_width,
                2
            )

        return obj

