def build_horse_model_v55_base(arm):

    import bpy
    import math

    from mathutils import Vector

    # ========================================================
    # BROKEN KNIGHT HORSE V55
    #
    # COHERENT HORSE SILHOUETTE
    #
    # V54 = 43 / 100
    #
    # KEEP:
    #
    # torso
    # saddle
    # blanket
    # saddlebags
    # bridle / tack
    #
    # REPLACE:
    #
    # neck
    # head
    # face
    # legs
    # hooves
    # mane
    # tail
    #
    # No separate cheek spheres.
    # No separate knee spheres.
    # No separate stifle spheres.
    # No separate hock spheres.
    #
    # ========================================================

    build_horse_model_v54_base(
        arm
    )

    print(
        "BROKEN_KNIGHT_HORSE_V55",
        "V54_BASE_COMPLETE"
    )

    # ========================================================
    # HELPERS
    # ========================================================

    def get_object(
        name
    ):

        return bpy.data.objects.get(
            name
        )

    def delete_prefix(
        prefix
    ):

        deleted = 0

        for obj in list(
            bpy.data.objects
        ):

            if obj.name.startswith(
                prefix
            ):

                bpy.data.objects.remove(
                    obj,
                    do_unlink=True
                )

                deleted += 1

        print(
            "V55_DELETE",
            prefix,
            deleted
        )

    def smooth(
        obj
    ):

        if obj is None:
            return

        if obj.type != "MESH":
            return

        for polygon in obj.data.polygons:
            polygon.use_smooth = True

    def bind_new(
        obj,
        group_name
    ):

        obj.parent = arm

        group = obj.vertex_groups.new(
            name=group_name
        )

        group.add(
            list(
                range(
                    len(
                        obj.data.vertices
                    )
                )
            ),
            1.0,
            "REPLACE"
        )

        modifier = obj.modifiers.new(
            "HorseRig",
            "ARMATURE"
        )

        modifier.object = arm

    def create_mesh(
        name,
        vertices,
        faces,
        material,
        group_name
    ):

        mesh = bpy.data.meshes.new(
            name + "Mesh"
        )

        mesh.from_pydata(
            vertices,
            [],
            faces
        )

        mesh.update()

        obj = bpy.data.objects.new(
            name,
            mesh
        )

        bpy.context.collection.objects.link(
            obj
        )

        obj.data.materials.append(
            material
        )

        smooth(
            obj
        )

        bind_new(
            obj,
            group_name
        )

        return obj

    def subdivide(
        obj,
        levels=1
    ):

        bpy.ops.object.select_all(
            action="DESELECT"
        )

        obj.select_set(
            True
        )

        bpy.context.view_layer.objects.active = obj

        modifier = obj.modifiers.new(
            "V55 Subdivision",
            "SUBSURF"
        )

        modifier.subdivision_type = "CATMULL_CLARK"
        modifier.levels = levels
        modifier.render_levels = levels

        bpy.ops.object.modifier_apply(
            modifier=modifier.name
        )

    def bevel(
        obj,
        width,
        segments=3
    ):

        bpy.ops.object.select_all(
            action="DESELECT"
        )

        obj.select_set(
            True
        )

        bpy.context.view_layer.objects.active = obj

        modifier = obj.modifiers.new(
            "V55 Bevel",
            "BEVEL"
        )

        modifier.width = width
        modifier.segments = segments

        bpy.ops.object.modifier_apply(
            modifier=modifier.name
        )

    def ellipsoid(
        name,
        location,
        scale,
        material,
        group_name
    ):

        bpy.ops.mesh.primitive_uv_sphere_add(
            segments=24,
            ring_count=16,
            location=location
        )

        obj = bpy.context.object

        obj.name = name
        obj.scale = Vector(
            scale
        )

        bpy.ops.object.transform_apply(
            location=False,
            rotation=False,
            scale=True
        )

        obj.data.materials.append(
            material
        )

        smooth(
            obj
        )

        bind_new(
            obj,
            group_name
        )

        return obj

    # ========================================================
    # CUSTOM ASYMMETRIC RING CAGE
    #
    # station:
    #
    # y
    # top z
    # high z
    # center z
    # low z
    # bottom z
    #
    # top half width
    # high half width
    # center half width
    # low half width
    # bottom half width
    #
    # This lets us build cheek / throat / jaw volume INTO
    # the mesh instead of adding visible balls.
    #
    # ========================================================

    def build_asymmetric_cage(
        name,
        stations,
        material,
        group_name,
        subdivision=1
    ):

        vertices = []
        faces = []

        ring_size = 10

        for s in stations:

            y = s[0]

            top_z = s[1]
            high_z = s[2]
            center_z = s[3]
            low_z = s[4]
            bottom_z = s[5]

            top_w = s[6]
            high_w = s[7]
            center_w = s[8]
            low_w = s[9]
            bottom_w = s[10]

            ring = [

                (
                    -top_w,
                    y,
                    top_z
                ),

                (
                    top_w,
                    y,
                    top_z
                ),

                (
                    high_w,
                    y,
                    high_z
                ),

                (
                    center_w,
                    y,
                    center_z
                ),

                (
                    low_w,
                    y,
                    low_z
                ),

                (
                    bottom_w,
                    y,
                    bottom_z
                ),

                (
                    -bottom_w,
                    y,
                    bottom_z
                ),

                (
                    -low_w,
                    y,
                    low_z
                ),

                (
                    -center_w,
                    y,
                    center_z
                ),

                (
                    -high_w,
                    y,
                    high_z
                ),
            ]

            vertices.extend(
                ring
            )

        for station_index in range(
            len(stations) - 1
        ):

            first = (
                station_index
                * ring_size
            )

            second = (
                station_index + 1
            ) * ring_size

            for ring_index in range(
                ring_size
            ):

                nxt = (
                    ring_index + 1
                ) % ring_size

                faces.append(
                    (
                        first + ring_index,
                        second + ring_index,
                        second + nxt,
                        first + nxt
                    )
                )

        faces.append(
            tuple(
                reversed(
                    range(
                        ring_size
                    )
                )
            )
        )

        last = (
            len(stations) - 1
        ) * ring_size

        faces.append(
            tuple(
                range(
                    last,
                    last + ring_size
                )
            )
        )

        obj = create_mesh(
            name,
            vertices,
            faces,
            material,
            group_name
        )

        if subdivision > 0:

            subdivide(
                obj,
                subdivision
            )

        smooth(
            obj
        )

        return obj

    # ========================================================
    # CONTINUOUS LIMB
    #
    # sections:
    #
    # y
    # z
    # absolute X distance from center
    # lateral radius
    # fore/aft depth radius
    #
    # Joint enlargement happens INSIDE the same mesh.
    #
    # ========================================================

    limb_profile = [

        (
            1.000,
            0.000
        ),

        (
            0.866,
            0.500
        ),

        (
            0.500,
            0.866
        ),

        (
            0.000,
            1.000
        ),

        (
            -0.500,
            0.866
        ),

        (
            -0.866,
            0.500
        ),

        (
            -1.000,
            0.000
        ),

        (
            -0.866,
            -0.500
        ),

        (
            -0.500,
            -0.866
        ),

        (
            0.000,
            -1.000
        ),

        (
            0.500,
            -0.866
        ),

        (
            0.866,
            -0.500
        ),
    ]

    def build_continuous_limb(
        name,
        side,
        sections,
        material,
        dark_material,
        group_name,
        dark_height
    ):

        centers = []

        for section in sections:

            centers.append(
                Vector(
                    (
                        side * section[2],
                        section[0],
                        section[1]
                    )
                )
            )

        vertices = []
        faces = []

        ring_size = len(
            limb_profile
        )

        def frame(
            index
        ):

            if index == 0:

                tangent = (
                    centers[1]
                    - centers[0]
                )

            elif index == len(
                centers
            ) - 1:

                tangent = (
                    centers[-1]
                    - centers[-2]
                )

            else:

                tangent = (
                    centers[index + 1]
                    - centers[index - 1]
                )

            if tangent.length < 0.000001:

                tangent = Vector(
                    (
                        0.0,
                        0.0,
                        -1.0
                    )
                )

            tangent.normalize()

            lateral = Vector(
                (
                    1.0,
                    0.0,
                    0.0
                )
            )

            depth_axis = lateral.cross(
                tangent
            )

            if depth_axis.length < 0.000001:

                depth_axis = Vector(
                    (
                        0.0,
                        1.0,
                        0.0
                    )
                )

            depth_axis.normalize()

            return (
                lateral,
                depth_axis
            )

        for index, section in enumerate(
            sections
        ):

            center = centers[
                index
            ]

            radius_x = section[3]
            radius_depth = section[4]

            lateral, depth_axis = frame(
                index
            )

            for px, py in limb_profile:

                point = (
                    center
                    + lateral
                    * (
                        px
                        * radius_x
                    )
                    + depth_axis
                    * (
                        py
                        * radius_depth
                    )
                )

                vertices.append(
                    tuple(point)
                )

        for section_index in range(
            len(sections) - 1
        ):

            first = (
                section_index
                * ring_size
            )

            second = (
                section_index + 1
            ) * ring_size

            for ring_index in range(
                ring_size
            ):

                nxt = (
                    ring_index + 1
                ) % ring_size

                faces.append(
                    (
                        first + ring_index,
                        second + ring_index,
                        second + nxt,
                        first + nxt
                    )
                )

        faces.append(
            tuple(
                reversed(
                    range(
                        ring_size
                    )
                )
            )
        )

        last = (
            len(sections) - 1
        ) * ring_size

        faces.append(
            tuple(
                range(
                    last,
                    last + ring_size
                )
            )
        )

        obj = create_mesh(
            name,
            vertices,
            faces,
            material,
            group_name
        )

        obj.data.materials.append(
            dark_material
        )

        # Dark points based on actual geometry height.

        for polygon in obj.data.polygons:

            average_z = (
                sum(
                    obj.data.vertices[
                        vertex_index
                    ].co.z
                    for vertex_index in polygon.vertices
                )
                / float(
                    len(
                        polygon.vertices
                    )
                )
            )

            if average_z < dark_height:

                polygon.material_index = 1

        subdivide(
            obj,
            1
        )

        smooth(
            obj
        )

        return obj

    # ========================================================
    # HOOF
    #
    # Actual wedge:
    #
    # narrower heel
    # wider toe
    # sloped upper surface
    #
    # ========================================================

    def build_hoof(
        name,
        center_x,
        heel_y,
        toe_y,
        material,
        group_name
    ):

        heel_half_width = 0.105
        toe_half_width = 0.145

        vertices = [

            (
                center_x - heel_half_width,
                heel_y,
                0.120
            ),

            (
                center_x + heel_half_width,
                heel_y,
                0.120
            ),

            (
                center_x - toe_half_width,
                toe_y,
                0.078
            ),

            (
                center_x + toe_half_width,
                toe_y,
                0.078
            ),

            (
                center_x - heel_half_width,
                heel_y,
                0.025
            ),

            (
                center_x + heel_half_width,
                heel_y,
                0.025
            ),

            (
                center_x - toe_half_width,
                toe_y,
                0.012
            ),

            (
                center_x + toe_half_width,
                toe_y,
                0.012
            ),
        ]

        faces = [

            (
                0,
                1,
                3,
                2
            ),

            (
                4,
                6,
                7,
                5
            ),

            (
                0,
                2,
                6,
                4
            ),

            (
                1,
                5,
                7,
                3
            ),

            (
                0,
                4,
                5,
                1
            ),

            (
                2,
                3,
                7,
                6
            ),
        ]

        obj = create_mesh(
            name,
            vertices,
            faces,
            material,
            group_name
        )

        bevel(
            obj,
            0.018,
            3
        )

        smooth(
            obj
        )

        return obj

    def side_shell(
        name,
        outline,
        center_x,
        material,
        group_name,
        bevel_width=0.0
    ):

        count = len(
            outline
        )

        vertices = []

        for y, z, width in outline:

            vertices.append(
                (
                    center_x - width,
                    y,
                    z
                )
            )

        for y, z, width in outline:

            vertices.append(
                (
                    center_x + width,
                    y,
                    z
                )
            )

        faces = [

            tuple(
                reversed(
                    range(
                        count
                    )
                )
            ),

            tuple(
                range(
                    count,
                    count * 2
                )
            ),
        ]

        for index in range(
            count
        ):

            nxt = (
                index + 1
            ) % count

            faces.append(
                (
                    index,
                    nxt,
                    count + nxt,
                    count + index
                )
            )

        obj = create_mesh(
            name,
            vertices,
            faces,
            material,
            group_name
        )

        if bevel_width > 0.0:

            bevel(
                obj,
                bevel_width,
                2
            )

        return obj

