    # ========================================================
    # CONTINUOUS LEG BUILDER
    #
    # No separate balls.
    #
    # No Catmull-Clark.
    #
    # Sections retain their intended angles.
    #
    # section:
    #
    # y
    # z
    # abs x
    # x radius
    # depth radius
    #
    # ========================================================

    limb_profile = [

        (
            1.000,
            0.000
        ),

        (
            0.707,
            0.707
        ),

        (
            0.000,
            1.000
        ),

        (
            -0.707,
            0.707
        ),

        (
            -1.000,
            0.000
        ),

        (
            -0.707,
            -0.707
        ),

        (
            0.000,
            -1.000
        ),

        (
            0.707,
            -0.707
        ),
    ]

    def build_limb(
        name,
        side,
        sections,
        group_name
    ):

        centers = [

            Vector(
                (
                    side * section[2],
                    section[0],
                    section[1]
                )
            )

            for section in sections
        ]

        vertices = []
        faces = []

        local_ring_size = len(
            limb_profile
        )

        def frame(
            index
        ):

            if index == 0:

                tangent = (
                    centers[1]
                    - centers[0]
                )

            elif index == len(
                centers
            ) - 1:

                tangent = (
                    centers[-1]
                    - centers[-2]
                )

            else:

                tangent = (
                    centers[index + 1]
                    - centers[index - 1]
                )

            if tangent.length < 0.000001:

                tangent = Vector(
                    (
                        0.0,
                        0.0,
                        -1.0
                    )
                )

            tangent.normalize()

            lateral = Vector(
                (
                    1.0,
                    0.0,
                    0.0
                )
            )

            depth_axis = lateral.cross(
                tangent
            )

            if depth_axis.length < 0.000001:

                depth_axis = Vector(
                    (
                        0.0,
                        1.0,
                        0.0
                    )
                )

            depth_axis.normalize()

            return (
                lateral,
                depth_axis
            )

        for index, section in enumerate(
            sections
        ):

            center = centers[
                index
            ]

            radius_x = section[3]
            radius_depth = section[4]

            lateral, depth_axis = frame(
                index
            )

            for px, py in limb_profile:

                point = (
                    center
                    + lateral
                    * (
                        px * radius_x
                    )
                    + depth_axis
                    * (
                        py * radius_depth
                    )
                )

                vertices.append(
                    tuple(point)
                )

        for section_index in range(
            len(sections) - 1
        ):

            first = (
                section_index
                * local_ring_size
            )

            second = (
                section_index + 1
            ) * local_ring_size

            for ring_index in range(
                local_ring_size
            ):

                nxt = (
                    ring_index + 1
                ) % local_ring_size

                faces.append(
                    (
                        first + ring_index,
                        second + ring_index,
                        second + nxt,
                        first + nxt
                    )
                )

        faces.append(
            tuple(
                reversed(
                    range(
                        local_ring_size
                    )
                )
            )
        )

        local_last = (
            len(sections) - 1
        ) * local_ring_size

        faces.append(
            tuple(
                range(
                    local_last,
                    local_last + local_ring_size
                )
            )
        )

        obj = create_mesh(
            name,
            vertices,
            faces,
            coat,
            group_name
        )

        obj.data.materials.append(
            dark
        )

        for polygon in obj.data.polygons:

            average_z = (
                sum(
                    obj.data.vertices[
                        vertex_index
                    ].co.z
                    for vertex_index in polygon.vertices
                )
                / float(
                    len(
                        polygon.vertices
                    )
                )
            )

            if average_z < 0.43:

                polygon.material_index = 1

        smooth(
            obj
        )

        return obj

