    # ========================================================

    limb_profile = [

        (
            1.00,
            0.00
        ),

        (
            0.50,
            0.82
        ),

        (
            -0.50,
            0.82
        ),

        (
            -1.00,
            0.00
        ),

        (
            -0.50,
            -0.82
        ),

        (
            0.50,
            -0.82
        ),
    ]

    def build_limb(
        name,
        side,
        sections,
        group_name
    ):

        # section:
        #
        # y
        # z
        # absolute x center
        # x radius
        # profile radius

        centers = [

            Vector(
                (
                    side * section[2],
                    section[0],
                    section[1]
                )
            )

            for section in sections
        ]

        vertices = []
        faces = []

        section_ring_size = len(
            limb_profile
        )

        for index, section in enumerate(
            sections
        ):

            center = centers[
                index
            ]

            radius_x = section[3]
            radius_profile = section[4]

            if index == 0:

                tangent = (
                    centers[1]
                    - centers[0]
                )

            elif index == len(
                centers
            ) - 1:

                tangent = (
                    centers[-1]
                    - centers[-2]
                )

            else:

                tangent = (
                    centers[index + 1]
                    - centers[index - 1]
                )

            if tangent.length < 0.000001:

                tangent = Vector(
                    (
                        0.0,
                        0.0,
                        -1.0
                    )
                )

            tangent.normalize()

            lateral = Vector(
                (
                    1.0,
                    0.0,
                    0.0
                )
            )

            profile_axis = lateral.cross(
                tangent
            )

            if profile_axis.length < 0.000001:

                profile_axis = Vector(
                    (
                        0.0,
                        1.0,
                        0.0
                    )
                )

            profile_axis.normalize()

            for px, py in limb_profile:

                point = (
                    center
                    + lateral
                    * (
                        px * radius_x
                    )
                    + profile_axis
                    * (
                        py * radius_profile
                    )
                )

                vertices.append(
                    tuple(
                        point
                    )
                )

        for section_index in range(
            len(sections) - 1
        ):

            first = (
                section_index
                * section_ring_size
            )

            second = (
                section_index + 1
            ) * section_ring_size

            for ring_index in range(
                section_ring_size
            ):

                next_index = (
                    ring_index + 1
                ) % section_ring_size

                faces.append(
                    (
                        first + ring_index,
                        second + ring_index,
                        second + next_index,
                        first + next_index
                    )
                )

        faces.append(
            tuple(
                reversed(
                    range(
                        section_ring_size
                    )
                )
            )
        )

        final_start = (
            len(sections) - 1
        ) * section_ring_size

        faces.append(
            tuple(
                range(
                    final_start,
                    final_start + section_ring_size
                )
            )
        )

        obj = create_mesh(
            name,
            vertices,
            faces,
            coat,
            group_name
        )

        obj.data.materials.append(
            dark
        )

        # Dark lower legs.

        for polygon in obj.data.polygons:

            average_z = (
                sum(
                    obj.data.vertices[
                        vertex_index
                    ].co.z
                    for vertex_index in polygon.vertices
                )
                / float(
                    len(
                        polygon.vertices
                    )
                )
            )

            if average_z < 0.42:
                polygon.material_index = 1

        bevel(
            obj,
            0.010,
            2,
            28.0
        )

        smooth(
            obj
        )

        return obj

